-- Añade el examen Mule-Dev-201 (Salesforce Certified MuleSoft Developer) con 500 preguntas en español e inglés.
-- Reparto por dominio: D1 35, D2 40, D3 50, D4 50, D5 35, D6 50, D7 50, D8 50, D9 40, D10 40, D11 25, D12 35.
-- Requisito: haber ejecutado antes 20261123_ccdvf_ingles.sql (columna questions.i18n).
-- Ejecutar en Supabase: SQL Editor > New query > pegar > Run.
-- Si el examen ya existe no hace nada, así que se puede ejecutar varias veces sin borrar
-- el progreso de nadie. Para reemplazar sus preguntas usa Administración > Importar.
do $do$
begin
  if exists (select 1 from public.exams where slug = 'salesforce-mulesoft-developer') then
    raise notice 'El examen salesforce-mulesoft-developer ya existe: no se ha modificado.';
  else
    perform public.import_exam_unchecked($exam${"slug":"salesforce-mulesoft-developer","name":"Salesforce Certified MuleSoft Developer","vendor":"Salesforce","code":"Mule-Dev-201","language":"es","description":"Preguntas de práctica escritas a partir de la guía oficial del examen de Salesforce (Mule 4). No son preguntas del examen real.","exam":{"questions":60,"minutes":120,"passing":"70%","mini":{"questions":20,"minutes":40}},"domains":[{"code":"D1","name":"Creating Application Networks","weight":7,"docs":[{"title":"Anypoint Exchange","url":"https://docs.mulesoft.com/exchange/"},{"title":"MuleSoft Developer credential (Trailhead)","url":"https://trailhead.salesforce.com/credentials/mulesoftdeveloperi"}]},{"code":"D2","name":"Designing APIs","weight":8,"docs":[{"title":"Design Center","url":"https://docs.mulesoft.com/design-center/"},{"title":"MuleSoft Developer credential (Trailhead)","url":"https://trailhead.salesforce.com/credentials/mulesoftdeveloperi"}]},{"code":"D3","name":"Accessing and Modifying Mule Events","weight":10,"docs":[{"title":"Mule event","url":"https://docs.mulesoft.com/mule-runtime/latest/about-mule-event"},{"title":"Core components","url":"https://docs.mulesoft.com/mule-runtime/latest/about-components"}]},{"code":"D4","name":"Structuring Mule Applications","weight":10,"docs":[{"title":"Core components","url":"https://docs.mulesoft.com/mule-runtime/latest/about-components"},{"title":"Mule runtime docs","url":"https://docs.mulesoft.com/mule-runtime/latest/"}]},{"code":"D5","name":"Building API Implementation Interfaces","weight":7,"docs":[{"title":"APIkit","url":"https://docs.mulesoft.com/apikit/latest/"}]},{"code":"D6","name":"Using Connectors","weight":10,"docs":[{"title":"Database Connector","url":"https://docs.mulesoft.com/db-connector/latest/"},{"title":"Core components","url":"https://docs.mulesoft.com/mule-runtime/latest/about-components"}]},{"code":"D7","name":"Processing Records","weight":10,"docs":[{"title":"For Each scope","url":"https://docs.mulesoft.com/mule-runtime/latest/for-each-scope-concept"},{"title":"Batch processing","url":"https://docs.mulesoft.com/mule-runtime/latest/batch-processing-concept"}]},{"code":"D8","name":"Transforming Data","weight":10,"docs":[{"title":"DataWeave","url":"https://docs.mulesoft.com/dataweave/latest/"}]},{"code":"D9","name":"Routing Events","weight":8,"docs":[{"title":"Choice router","url":"https://docs.mulesoft.com/mule-runtime/latest/choice-router-concept"},{"title":"Scatter-Gather router","url":"https://docs.mulesoft.com/mule-runtime/latest/scatter-gather-concept"}]},{"code":"D10","name":"Handling Errors","weight":8,"docs":[{"title":"On Error scopes","url":"https://docs.mulesoft.com/mule-runtime/latest/on-error-scope-concept"}]},{"code":"D11","name":"Debugging and Troubleshooting Mule Applications","weight":5,"docs":[{"title":"MUnit","url":"https://docs.mulesoft.com/munit/latest/"}]},{"code":"D12","name":"Deploying and Managing APIs and Integrations","weight":7,"docs":[{"title":"API Manager","url":"https://docs.mulesoft.com/api-manager/latest/"},{"title":"CloudHub","url":"https://docs.mulesoft.com/cloudhub/"}]}],"questions":[{"domain":"D1","source":"bank","stem":"¿Qué es una red de aplicaciones (application network) según MuleSoft?","options":["Una red privada virtual que conecta las oficinas y los centros de datos de la empresa","Un conjunto de aplicaciones, datos y dispositivos conectados mediante APIs reutilizables","Un clúster de servidores Mule desplegados en la misma subred","Un catálogo de aplicaciones móviles publicado en una tienda"],"correct":[1],"explanation":"La red de aplicaciones surge de exponer capacidades como APIs reutilizables.","i18n":{"en":{"stem":"What is an application network according to MuleSoft?","options":["A VPN linking the company's offices and data centers","A set of apps, data and devices connected through reusable APIs","A cluster of Mule servers on the same subnet","A mobile app catalog published in a store"],"explanation":"The application network emerges from exposing capabilities as reusable APIs."}}},{"domain":"D1","source":"bank","stem":"¿Qué tres capas propone la conectividad dirigida por API (API-led connectivity)?","options":["System, Process y Experience","Front-end, back-end y base de datos","Presentación, negocio y datos, desplegadas como un monolito","Bronce, plata y oro"],"correct":[0],"explanation":"System APIs exponen sistemas, Process APIs orquestan y Experience APIs sirven a canales.","i18n":{"en":{"stem":"Which three layers does API-led connectivity propose?","options":["System, Process and Experience","Front end, back end and database","Presentation, business and data, deployed as a monolith","Bronze, silver and gold"],"explanation":"System APIs expose systems, Process APIs orchestrate, Experience APIs serve channels."}}},{"domain":"D1","source":"bank","stem":"¿Qué capa de API desbloquea datos de un sistema de registro como SAP o una base de datos?","options":["API de proxy de seguridad","Experience API adaptada a la app móvil del cliente","System API","Process API que combina varios sistemas"],"correct":[2],"explanation":"Las System APIs ocultan la complejidad del sistema subyacente.","i18n":{"en":{"stem":"Which API layer unlocks data from a system of record like SAP or a database?","options":["Security proxy API","Experience API tailored to the customer mobile app","System API","Process API combining several systems"],"explanation":"System APIs hide the underlying system's complexity."}}},{"domain":"D1","source":"bank","stem":"¿Qué capa adapta los datos al formato que necesita un canal concreto, como una app móvil?","options":["Process API de orquestación","Un conector de base de datos","System API conectada directamente al ERP","Experience API"],"correct":[3],"explanation":"Las Experience APIs sirven a consumidores específicos.","i18n":{"en":{"stem":"Which layer shapes data for a specific channel like a mobile app?","options":["Orchestration Process API","A database connector","System API wired directly to the ERP","Experience API"],"explanation":"Experience APIs serve specific consumers."}}},{"domain":"D1","source":"bank","stem":"¿Qué capa combina datos de varios sistemas para implementar un proceso de negocio, como el estado de un pedido?","options":["API Gateway","Process API","Experience API","System API"],"correct":[1],"explanation":"Las Process APIs orquestan System APIs.","i18n":{"en":{"stem":"Which layer combines data from several systems to implement a business process like order status?","options":["API Gateway","Process API","Experience API","System API"],"explanation":"Process APIs orchestrate System APIs."}}},{"domain":"D1","source":"bank","stem":"¿Qué ventaja principal tiene el enfoque API-led frente a integraciones punto a punto?","options":["Que cada integración es más rápida de construir la primera vez","Que no requiere gobierno","Que elimina la necesidad de documentar las APIs","Reutilización y menor acoplamiento entre sistemas"],"correct":[3],"explanation":"Las APIs reutilizables reducen el coste de cambio y aceleran nuevos proyectos.","i18n":{"en":{"stem":"What's the main benefit of API-led over point-to-point integrations?","options":["Each integration is faster to build the first time","It needs no governance","It removes the need to document APIs","Reuse and lower coupling between systems"],"explanation":"Reusable APIs reduce change cost and speed up new projects."}}},{"domain":"D1","source":"bank","stem":"¿Qué es un Centro para la Habilitación (C4E)?","options":["Un equipo transversal que promueve la reutilización y buenas prácticas de APIs","Un equipo de soporte de segundo nivel que corrige errores de producción de todas las APIs","Un centro de datos donde se ejecuta CloudHub","Una herramienta de pruebas automatizadas"],"correct":[0],"explanation":"El C4E habilita a los equipos con activos, plantillas y guías.","i18n":{"en":{"stem":"What is a Center for Enablement (C4E)?","options":["A cross-functional team promoting API reuse and best practices","A second-level support team fixing production bugs across all APIs","A data center where CloudHub runs","An automated testing tool"],"explanation":"The C4E enables teams with assets, templates and guidance."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos actividades son típicas de un C4E? (Elige 2)","options":["Desarrollar todas las APIs de la empresa en exclusiva","Definir estándares y plantillas de APIs","Publicar activos reutilizables en Exchange","Gestionar las nóminas del equipo de integración","Aprobar manualmente cada despliegue de cada equipo"],"correct":[1,2],"explanation":"El C4E es un modelo federado de habilitación, no un cuello de botella.","i18n":{"en":{"stem":"Which two activities are typical of a C4E? (Choose 2)","options":["Building every company API exclusively","Defining API standards and templates","Publishing reusable assets to Exchange","Managing the integration team's payroll","Manually approving every team's deployments"],"explanation":"The C4E is a federated enablement model, not a bottleneck."}}},{"domain":"D1","source":"bank","stem":"¿Qué es Anypoint Exchange?","options":["Un servidor de correo para notificaciones","Un repositorio privado de código fuente donde se guardan los proyectos Mule","Un catálogo para publicar y descubrir APIs y activos reutilizables","Un entorno de ejecución de Mule"],"correct":[2],"explanation":"Exchange almacena especificaciones, fragmentos, conectores y plantillas.","i18n":{"en":{"stem":"What is Anypoint Exchange?","options":["A mail server for notifications","A private source repository where Mule projects are stored","A catalog to publish and discover APIs and reusable assets","A Mule runtime environment"],"explanation":"Exchange stores specs, fragments, connectors and templates."}}},{"domain":"D1","source":"bank","stem":"¿Qué componente de Anypoint Platform permite diseñar especificaciones de API en RAML u OAS?","options":["Design Center (API Designer)","Anypoint MQ","Runtime Manager","Access Management con plantillas de roles"],"correct":[0],"explanation":"Design Center incluye el editor de especificaciones.","i18n":{"en":{"stem":"Which Anypoint Platform component designs API specs in RAML or OAS?","options":["Design Center (API Designer)","Anypoint MQ","Runtime Manager","Access Management with role templates"],"explanation":"Design Center includes the spec editor."}}},{"domain":"D1","source":"bank","stem":"¿Qué componente gestiona políticas, versiones y SLA de APIs desplegadas?","options":["API Manager","Exchange","Anypoint Studio","Design Center"],"correct":[0],"explanation":"API Manager aplica políticas y gestiona instancias de API.","i18n":{"en":{"stem":"Which component manages policies, versions and SLAs of deployed APIs?","options":["API Manager","Exchange","Anypoint Studio","Design Center"],"explanation":"API Manager applies policies and manages API instances."}}},{"domain":"D1","source":"bank","stem":"¿Qué componente despliega y supervisa aplicaciones Mule?","options":["Anypoint Visualizer únicamente","API Designer","Runtime Manager","Exchange"],"correct":[2],"explanation":"Runtime Manager gestiona despliegues en CloudHub y otros destinos.","i18n":{"en":{"stem":"Which component deploys and monitors Mule applications?","options":["Only Anypoint Visualizer","API Designer","Runtime Manager","Exchange"],"explanation":"Runtime Manager manages deployments to CloudHub and other targets."}}},{"domain":"D1","source":"bank","stem":"¿Qué es Anypoint Studio?","options":["Un servicio de colas de mensajes","El IDE de escritorio para desarrollar aplicaciones Mule","El panel de facturación de MuleSoft","Un portal web para que los consumidores prueben las APIs publicadas"],"correct":[1],"explanation":"Studio es el entorno basado en Eclipse para flujos Mule.","i18n":{"en":{"stem":"What is Anypoint Studio?","options":["A message queue service","The desktop IDE for building Mule applications","MuleSoft's billing dashboard","A web portal for consumers to try published APIs"],"explanation":"Studio is the Eclipse-based environment for Mule flows."}}},{"domain":"D1","source":"bank","stem":"¿Qué indica el ciclo de vida de una API en Anypoint Platform?","options":["Solo implementar y desplegar","Diseñar, simular, validar, implementar, desplegar y gestionar","Codificar primero, desplegar en producción y documentar al final si sobra tiempo","Desplegar en producción y diseñar después"],"correct":[1],"explanation":"El enfoque design-first valida con consumidores antes de implementar.","i18n":{"en":{"stem":"What does the API lifecycle look like in Anypoint Platform?","options":["Only implement and deploy","Design, mock, validate, implement, deploy and manage","Code first, deploy to production and document at the end if there's time","Deploy to production and design later"],"explanation":"Design-first validates with consumers before implementing."}}},{"domain":"D1","source":"bank","stem":"¿Para qué sirve el servicio de simulación (mocking service) de API Designer?","options":["Probar la API con respuestas de ejemplo antes de implementarla","Ejecutar pruebas de carga en producción","Generar automáticamente el código Java de la implementación a partir de la especificación","Cifrar las respuestas de la API"],"correct":[0],"explanation":"Permite a consumidores validar el contrato temprano.","i18n":{"en":{"stem":"What is API Designer's mocking service for?","options":["Testing the API with example responses before implementing it","Running load tests in production","Auto-generating the Java implementation code from the spec","Encrypting API responses"],"explanation":"It lets consumers validate the contract early."}}},{"domain":"D1","source":"bank","stem":"¿Qué es un portal público de API (API portal / Exchange portal)?","options":["Un panel interno de monitorización de servidores y del consumo de CPU de cada worker","Una herramienta para editar flujos Mule","Un registro de errores","Un sitio para que desarrolladores externos descubran y soliciten acceso a APIs"],"correct":[3],"explanation":"Public portals exponen documentación y solicitud de acceso.","i18n":{"en":{"stem":"What is a public API portal?","options":["An internal dashboard monitoring servers and each worker's CPU usage","A tool to edit Mule flows","An error log","A site for external developers to discover and request API access"],"explanation":"Public portals expose docs and access requests."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos elementos favorecen la reutilización de APIs en la red de aplicaciones? (Elige 2)","options":["Crear una API nueva para cada consumidor","Publicar especificaciones en Exchange","Duplicar la lógica en cada proyecto","Documentar ejemplos y casos de uso","Ocultar las APIs existentes a otros equipos"],"correct":[1,3],"explanation":"Descubrimiento y documentación impulsan el consumo.","i18n":{"en":{"stem":"Which two elements foster API reuse in the application network? (Choose 2)","options":["Building a new API for each consumer","Publishing specs to Exchange","Duplicating logic in each project","Documenting examples and use cases","Hiding existing APIs from other teams"],"explanation":"Discovery and documentation drive consumption."}}},{"domain":"D1","source":"bank","stem":"¿Qué métrica refleja el valor de una API dentro de la red de aplicaciones?","options":["Tamaño del archivo JAR desplegado","Número de consumidores y reutilizaciones","Número de flujos privados","Número de líneas de código de la implementación"],"correct":[1],"explanation":"La reutilización indica valor de la API.","i18n":{"en":{"stem":"Which metric reflects an API's value within the application network?","options":["Size of the deployed JAR","Number of consumers and reuses","Number of private flows","Lines of code in the implementation"],"explanation":"Reuse indicates API value."}}},{"domain":"D1","source":"bank","stem":"¿Qué capa de API debería llamar directamente una app móvil en una arquitectura API-led?","options":["La System API del ERP directamente","La base de datos con un conector JDBC","Una Experience API","Una cola de mensajes"],"correct":[2],"explanation":"Los canales consumen Experience APIs.","i18n":{"en":{"stem":"Which API layer should a mobile app call directly in an API-led architecture?","options":["The ERP's System API directly","The database with a JDBC connector","An Experience API","A message queue"],"explanation":"Channels consume Experience APIs."}}},{"domain":"D1","source":"bank","stem":"¿Qué riesgo tiene que cada canal llame directamente a los sistemas de registro?","options":["Mejor seguridad por defecto","Menos tráfico de red","Mayor reutilización y menos mantenimiento","Alto acoplamiento y lógica duplicada"],"correct":[3],"explanation":"Las integraciones punto a punto son frágiles.","i18n":{"en":{"stem":"What's the risk of each channel calling systems of record directly?","options":["Better security by default","Less network traffic","More reuse and less maintenance","High coupling and duplicated logic"],"explanation":"Point-to-point integrations are brittle."}}},{"domain":"D1","source":"bank","stem":"¿Qué es Anypoint Visualizer?","options":["Una herramienta de facturación","Un editor gráfico de transformaciones DataWeave con vista previa de datos de ejemplo","Una vista gráfica de las aplicaciones y sus dependencias en tiempo de ejecución","Un diseñador de páginas web"],"correct":[2],"explanation":"Visualizer muestra la topología de la red de aplicaciones.","i18n":{"en":{"stem":"What is Anypoint Visualizer?","options":["A billing tool","A graphical DataWeave transformation editor with sample data preview","A graphical view of apps and their runtime dependencies","A web page designer"],"explanation":"Visualizer shows the application network topology."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipo de activo de Exchange permite compartir tipos y ejemplos entre varias especificaciones RAML?","options":["Política personalizada de seguridad","Plantilla de aplicación móvil","Conector de base de datos","Fragmento de API (API fragment)"],"correct":[3],"explanation":"Los fragmentos RAML reutilizan tipos, traits y ejemplos.","i18n":{"en":{"stem":"Which Exchange asset shares types and examples across several RAML specs?","options":["Custom security policy","Mobile app template","Database connector","API fragment"],"explanation":"RAML fragments reuse types, traits and examples."}}},{"domain":"D1","source":"bank","stem":"¿Qué cambio organizativo impulsa MuleSoft con el modelo de operación API-led?","options":["IT pasa de entregar proyectos a habilitar el autoservicio","Externalizar todas las integraciones","Eliminar los equipos de negocio","Centralizar todo el desarrollo de integraciones en un único equipo de IT"],"correct":[0],"explanation":"El modelo de entrega se centra en producir y consumir activos.","i18n":{"en":{"stem":"Which organizational change does MuleSoft's API-led operating model drive?","options":["IT shifts from delivering projects to enabling self-service","Outsourcing all integrations","Eliminating business teams","Centralizing all integration development in a single IT team"],"explanation":"The delivery model focuses on producing and consuming assets."}}},{"domain":"D1","source":"bank","stem":"¿Qué hace un consumidor de API para solicitar acceso a una API gestionada?","options":["Llama sin credenciales","Solicita acceso desde Exchange y obtiene credenciales de cliente","Pide al administrador la contraseña del servidor donde corre la aplicación","Descarga el código fuente de la API"],"correct":[1],"explanation":"Se registra una aplicación cliente con client ID y secret.","i18n":{"en":{"stem":"What does an API consumer do to request access to a managed API?","options":["Call without credentials","Request access from Exchange and get client credentials","Asks the admin for the password of the server running the app","Download the API source code"],"explanation":"A client application is registered with client ID and secret."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos componentes de Anypoint Platform intervienen al gobernar una API en producción? (Elige 2)","options":["Runtime Manager","Anypoint Studio únicamente","API Manager","El navegador del consumidor","Un editor de texto local"],"correct":[0,2],"explanation":"API Manager aplica políticas y Runtime Manager gestiona la app.","i18n":{"en":{"stem":"Which two Anypoint components are involved in governing a production API? (Choose 2)","options":["Runtime Manager","Only Anypoint Studio","API Manager","The consumer's browser","A local text editor"],"explanation":"API Manager applies policies; Runtime Manager manages the app."}}},{"domain":"D1","source":"bank","stem":"¿Qué significa diseño primero (design-first) en MuleSoft?","options":["Diseñar la base de datos primero","Escribir la implementación y generar la especificación después","Acordar el contrato de la API antes de implementarla","Diseñar la interfaz gráfica antes que la API"],"correct":[2],"explanation":"El contrato guía a productores y consumidores.","i18n":{"en":{"stem":"What does design-first mean in MuleSoft?","options":["Designing the database first","Writing the implementation and generating the spec later","Agreeing the API contract before implementing it","Designing the UI before the API"],"explanation":"The contract guides producers and consumers."}}},{"domain":"D1","source":"bank","stem":"¿Qué ventaja tiene que las System APIs oculten el sistema de origen?","options":["Poder cambiar el sistema sin afectar a los consumidores","Que los consumidores puedan consultar directamente las tablas internas","Que la API sea más lenta","Que se elimine la seguridad"],"correct":[0],"explanation":"Aíslan cambios del back-end.","i18n":{"en":{"stem":"What's the benefit of System APIs hiding the source system?","options":["The system can change without affecting consumers","Consumers can query the internal tables directly","The API is slower","Security is removed"],"explanation":"They isolate back-end changes."}}},{"domain":"D1","source":"bank","stem":"¿Qué es Anypoint MQ?","options":["Una política de seguridad","Un lenguaje de consultas","Un monitor de calidad de APIs que mide la latencia de cada endpoint","Un servicio de mensajería en la nube de MuleSoft"],"correct":[3],"explanation":"Anypoint MQ ofrece colas e intercambios gestionados.","i18n":{"en":{"stem":"What is Anypoint MQ?","options":["A security policy","A query language","An API quality monitor measuring each endpoint's latency","MuleSoft's cloud messaging service"],"explanation":"Anypoint MQ provides managed queues and exchanges."}}},{"domain":"D1","source":"bank","stem":"¿Qué componente gestiona usuarios, roles y unidades de negocio en Anypoint Platform?","options":["Access Management","API Designer","Exchange","Runtime Manager, desde la pestaña de ajustes"],"correct":[0],"explanation":"Access Management controla identidades y permisos.","i18n":{"en":{"stem":"Which component manages users, roles and business groups in Anypoint Platform?","options":["Access Management","API Designer","Exchange","Runtime Manager, from its settings tab"],"explanation":"Access Management controls identities and permissions."}}},{"domain":"D1","source":"bank","stem":"¿Qué son los entornos (environments) en Anypoint Platform?","options":["Tipos de conectores","Carpetas de Exchange","Espacios separados como Sandbox y Producción para desplegar apps","Versiones de Anypoint Studio instaladas en los equipos de los desarrolladores"],"correct":[2],"explanation":"Los entornos separan ciclos de vida.","i18n":{"en":{"stem":"What are environments in Anypoint Platform?","options":["Connector types","Exchange folders","Separate spaces like Sandbox and Production for deploying apps","Anypoint Studio versions installed on developers' machines"],"explanation":"Environments separate lifecycles."}}},{"domain":"D1","source":"bank","stem":"¿Qué indica que una API sea \"producto\" en un enfoque API-led?","options":["Que se distribuye como un archivo ZIP descargable para cada consumidor","No tiene contrato","Se vende siempre a terceros","Tiene consumidores, documentación, versión y responsable"],"correct":[3],"explanation":"Las APIs se gestionan como productos con ciclo de vida.","i18n":{"en":{"stem":"What does treating an API as a product mean in API-led?","options":["It's distributed as a downloadable ZIP for each consumer","It has no contract","It's always sold to third parties","It has consumers, docs, versioning and an owner"],"explanation":"APIs are managed as products with a lifecycle."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos beneficios de negocio aporta una red de aplicaciones madura? (Elige 2)","options":["Más integraciones punto a punto","Mayor dependencia de cada sistema","Eliminar la necesidad de seguridad","Mayor velocidad para lanzar nuevos proyectos","Menor coste de integración a largo plazo"],"correct":[3,4],"explanation":"Agilidad y eficiencia por reutilización.","i18n":{"en":{"stem":"Which two business benefits does a mature application network bring? (Choose 2)","options":["More point-to-point integrations","Greater dependence on each system","No need for security","Faster launch of new projects","Lower long-term integration cost"],"explanation":"Agility and efficiency through reuse."}}},{"domain":"D1","source":"bank","stem":"¿Qué es un activo de tipo plantilla (template) en Exchange?","options":["Una especificación RAML vacía con la estructura mínima de carpetas","Un informe de facturación","Un usuario de prueba","Un proyecto Mule reutilizable como punto de partida"],"correct":[3],"explanation":"Las plantillas aceleran implementaciones comunes.","i18n":{"en":{"stem":"What is a template asset in Exchange?","options":["An empty RAML spec with the minimum folder structure","A billing report","A test user","A reusable Mule project as a starting point"],"explanation":"Templates speed common implementations."}}},{"domain":"D1","source":"bank","stem":"¿Qué perfil de usuario consume principalmente las Experience APIs?","options":["Desarrolladores de aplicaciones y canales","Equipos de infraestructura de red","Administradores de bases de datos de los sistemas de registro","Auditores financieros"],"correct":[0],"explanation":"Las Experience APIs sirven a desarrolladores de front-end y apps.","i18n":{"en":{"stem":"Which user profile mainly consumes Experience APIs?","options":["App and channel developers","Network infrastructure teams","Database administrators of the systems of record","Financial auditors"],"explanation":"Experience APIs serve front-end and app developers."}}},{"domain":"D1","source":"bank","stem":"¿Qué recomienda MuleSoft al diseñar una nueva integración?","options":["Buscar primero activos reutilizables en Exchange","Escribir todo desde cero para tener control","Evitar documentar","Llamar directamente a la base de datos desde la app"],"correct":[0],"explanation":"La reutilización es el primer paso.","i18n":{"en":{"stem":"What does MuleSoft recommend when designing a new integration?","options":["Search Exchange for reusable assets first","Write everything from scratch for control","Avoid documenting","Call the database directly from the app"],"explanation":"Reuse comes first."}}},{"domain":"D2","source":"bank","stem":"¿Qué es RAML?","options":["Un protocolo de mensajería","Un formato de logs de Mule","Un lenguaje de transformación de datos que sustituye a DataWeave","Un lenguaje basado en YAML para modelar APIs REST"],"correct":[3],"explanation":"RESTful API Modeling Language.","i18n":{"en":{"stem":"What is RAML?","options":["A messaging protocol","A Mule log format","A data transformation language replacing DataWeave","A YAML-based language for modeling REST APIs"],"explanation":"RESTful API Modeling Language."}}},{"domain":"D2","source":"bank","stem":"¿Cómo se define un recurso en RAML?","options":["Con un comentario #resource","Con una etiqueta XML <resource>","Con una ruta que empieza por barra, como /orders","Con la palabra clave resource seguida del nombre del recurso"],"correct":[2],"explanation":"Los recursos son claves que empiezan por /.","i18n":{"en":{"stem":"How is a resource defined in RAML?","options":["With a #resource comment","With an XML <resource> tag","With a path starting with a slash, like /orders","With the resource keyword followed by the resource name"],"explanation":"Resources are keys starting with /."}}},{"domain":"D2","source":"bank","stem":"¿Cómo se declara un parámetro de URI en un recurso RAML?","options":["Entre llaves en la ruta, como /orders/{orderId}","Como ?orderId al final de la ruta","Con el prefijo $ en la ruta","Con dos puntos, como /orders/:orderId, obligatoriamente"],"correct":[0],"explanation":"Los URI parameters se declaran con {}.","i18n":{"en":{"stem":"How is a URI parameter declared in a RAML resource?","options":["In braces in the path, like /orders/{orderId}","As ?orderId at the end of the path","With a $ prefix in the path","With a colon, like /orders/:orderId, mandatorily"],"explanation":"URI parameters use {}."}}},{"domain":"D2","source":"bank","stem":"¿Dónde se definen los parámetros de consulta (query parameters) en RAML?","options":["En el cuerpo de la respuesta","En las cabeceras de seguridad","En la sección uriParameters del recurso padre de la ruta","En la sección queryParameters del método"],"correct":[3],"explanation":"queryParameters se define bajo el método.","i18n":{"en":{"stem":"Where are query parameters defined in RAML?","options":["In the response body","In security headers","In the parent resource's uriParameters section","In the method's queryParameters section"],"explanation":"queryParameters is defined under the method."}}},{"domain":"D2","source":"bank","stem":"¿Qué diferencia hay entre un parámetro de URI y uno de consulta?","options":["El de URI siempre es opcional","El de URI identifica el recurso; el de consulta filtra o modifica la respuesta","El de consulta identifica el recurso y el de URI filtra o modifica la respuesta","Son lo mismo con distinto nombre"],"correct":[1],"explanation":"/orders/{id} vs /orders?status=open.","i18n":{"en":{"stem":"What's the difference between a URI parameter and a query parameter?","options":["URI is always optional","URI identifies the resource; query filters or modifies the response","Query identifies the resource and URI filters or modifies the response","They're the same with different names"],"explanation":"/orders/{id} vs /orders?status=open."}}},{"domain":"D2","source":"bank","stem":"¿Qué método HTTP se usa normalmente para crear un recurso nuevo?","options":["GET","DELETE","POST","HEAD"],"correct":[2],"explanation":"POST crea; PUT reemplaza; PATCH modifica parcialmente.","i18n":{"en":{"stem":"Which HTTP method usually creates a new resource?","options":["GET","DELETE","POST","HEAD"],"explanation":"POST creates; PUT replaces; PATCH partially updates."}}},{"domain":"D2","source":"bank","stem":"¿Qué método HTTP es idempotente y reemplaza un recurso completo?","options":["CONNECT","PATCH en todos los casos","POST","PUT"],"correct":[3],"explanation":"PUT es idempotente; POST no.","i18n":{"en":{"stem":"Which HTTP method is idempotent and replaces a whole resource?","options":["CONNECT","PATCH in all cases","POST","PUT"],"explanation":"PUT is idempotent; POST isn't."}}},{"domain":"D2","source":"bank","stem":"¿Qué código de estado HTTP indica que un recurso se ha creado correctamente?","options":["200 OK, que es el único válido para creaciones","201 Created","204 No Content","302 Found"],"correct":[1],"explanation":"201 es el código estándar para creación.","i18n":{"en":{"stem":"Which HTTP status indicates a resource was created successfully?","options":["200 OK, the only valid one for creation","201 Created","204 No Content","302 Found"],"explanation":"201 is the standard creation code."}}},{"domain":"D2","source":"bank","stem":"¿Qué código HTTP indica que el recurso solicitado no existe?","options":["500 Internal Server Error","404 Not Found","400 Bad Request","401 Unauthorized"],"correct":[1],"explanation":"404 = no encontrado.","i18n":{"en":{"stem":"Which HTTP code indicates the requested resource doesn't exist?","options":["500 Internal Server Error","404 Not Found","400 Bad Request","401 Unauthorized"],"explanation":"404 = not found."}}},{"domain":"D2","source":"bank","stem":"¿Qué dos códigos de estado indican errores del cliente? (Elige 2)","options":["401 Unauthorized","400 Bad Request","201 Created","503 Service Unavailable","500 Internal Server Error"],"correct":[0,1],"explanation":"4xx = error del cliente; 5xx = error del servidor.","i18n":{"en":{"stem":"Which two status codes indicate client errors? (Choose 2)","options":["401 Unauthorized","400 Bad Request","201 Created","503 Service Unavailable","500 Internal Server Error"],"explanation":"4xx = client error; 5xx = server error."}}},{"domain":"D2","source":"bank","stem":"¿Qué permite un tipo de datos (data type) en RAML?","options":["Definir la estructura de cuerpos y parámetros para validar y documentar","Definir la configuración del servidor HTTP","Definir las políticas de seguridad que API Manager aplica a cada instancia","Definir el número de workers"],"correct":[0],"explanation":"Los types describen objetos, propiedades y restricciones.","i18n":{"en":{"stem":"What does a RAML data type allow?","options":["Defining body and parameter structure for validation and docs","Defining HTTP server configuration","Defining the security policies API Manager applies to each instance","Defining the number of workers"],"explanation":"Types describe objects, properties and constraints."}}},{"domain":"D2","source":"bank","stem":"¿Cómo se indica que una propiedad de un tipo RAML es opcional?","options":["Poniéndola al final de la lista de propiedades del tipo","Añadiendo ? al nombre o required: false","Con el prefijo optional-","Escribiéndola en mayúsculas"],"correct":[1],"explanation":"Por defecto las propiedades son obligatorias.","i18n":{"en":{"stem":"How is a RAML type property marked optional?","options":["Putting it last in the type's property list","Adding ? to the name or required: false","With an optional- prefix","Writing it in capitals"],"explanation":"Properties are required by default."}}},{"domain":"D2","source":"bank","stem":"¿Qué es un trait en RAML?","options":["Un recurso anidado","Un ejemplo de respuesta","Un tipo de dato numérico con límites mínimo y máximo para los parámetros","Un conjunto reutilizable de características de método, como paginación"],"correct":[3],"explanation":"Los traits se aplican con is: [traitName].","i18n":{"en":{"stem":"What is a RAML trait?","options":["A nested resource","A response example","A numeric data type with min and max bounds for parameters","A reusable set of method characteristics, like pagination"],"explanation":"Traits are applied with is: [traitName]."}}},{"domain":"D2","source":"bank","stem":"¿Qué es un resourceType en RAML?","options":["Un esquema de seguridad","Una plantilla reutilizable para recursos con métodos comunes","Un fragmento de documentación","Un tipo de dato reutilizable para el cuerpo de las peticiones POST"],"correct":[1],"explanation":"Se aplica con type: collection, por ejemplo.","i18n":{"en":{"stem":"What is a RAML resourceType?","options":["A security scheme","A reusable template for resources with common methods","A documentation fragment","A reusable data type for POST request bodies"],"explanation":"Applied with type: collection, for example."}}},{"domain":"D2","source":"bank","stem":"¿Qué palabra clave de RAML incluye contenido de otro archivo?","options":["use only","require","!include","import"],"correct":[2],"explanation":"!include inserta archivos externos.","i18n":{"en":{"stem":"Which RAML keyword includes another file's content?","options":["use only","require","!include","import"],"explanation":"!include inserts external files."}}},{"domain":"D2","source":"bank","stem":"¿Qué se usa en RAML para referenciar una librería de tipos y traits?","options":["!include en cada propiedad","import from","uses con un alias","extends"],"correct":[2],"explanation":"uses: lib: libraries/common.raml.","i18n":{"en":{"stem":"What does RAML use to reference a library of types and traits?","options":["!include on each property","import from","uses with an alias","extends"],"explanation":"uses: lib: libraries/common.raml."}}},{"domain":"D2","source":"bank","stem":"¿Qué define un securitySchemes en RAML?","options":["Los workers de CloudHub","Los tipos de datos que se cifran en el cuerpo de la petición","Cómo se autentican las peticiones, por ejemplo OAuth 2.0","Los códigos de error 500"],"correct":[2],"explanation":"Se documenta el mecanismo de autenticación.","i18n":{"en":{"stem":"What does securitySchemes define in RAML?","options":["CloudHub workers","The data types encrypted in the request body","How requests authenticate, e.g. OAuth 2.0","500 error codes"],"explanation":"It documents the auth mechanism."}}},{"domain":"D2","source":"bank","stem":"¿Qué ventaja tiene incluir ejemplos (examples) en la especificación?","options":["Que se omite la validación","Que se cifran los datos","Que la API implementada se ejecuta más rápido en producción","El mocking service devuelve respuestas realistas"],"correct":[3],"explanation":"Los ejemplos alimentan simulación y documentación.","i18n":{"en":{"stem":"What's the benefit of including examples in the spec?","options":["Validation is skipped","Data is encrypted","The implemented API runs faster in production","The mocking service returns realistic responses"],"explanation":"Examples feed mocking and docs."}}},{"domain":"D2","source":"bank","stem":"¿Qué indica la cabecera Content-Type en una petición REST?","options":["El tipo de respuesta que el cliente acepta recibir del servidor","La versión de la API","El tipo de medio del cuerpo enviado, como application/json","El método HTTP"],"correct":[2],"explanation":"Accept indica lo que el cliente acepta.","i18n":{"en":{"stem":"What does the Content-Type header indicate in a REST request?","options":["The response type the client accepts from the server","The API version","The media type of the sent body, like application/json","The HTTP method"],"explanation":"Accept indicates what the client accepts."}}},{"domain":"D2","source":"bank","stem":"¿Qué cabecera usa el cliente para indicar el formato de respuesta que prefiere?","options":["Host","Authorization","Accept","Content-Type"],"correct":[2],"explanation":"Negociación de contenido.","i18n":{"en":{"stem":"Which header does the client use for its preferred response format?","options":["Host","Authorization","Accept","Content-Type"],"explanation":"Content negotiation."}}},{"domain":"D2","source":"bank","stem":"¿Qué buena práctica de diseño REST conviene para nombrar recursos?","options":["Nombres en mayúsculas con espacios","Sustantivos en plural, como /customers","Usar siempre POST para todo","Verbos en la ruta que describan la acción, como /getCustomers"],"correct":[1],"explanation":"Los recursos son sustantivos; los verbos los da el método.","i18n":{"en":{"stem":"Which REST naming practice is recommended for resources?","options":["Uppercase names with spaces","Plural nouns, like /customers","Always POST for everything","Verbs in the path describing the action, like /getCustomers"],"explanation":"Resources are nouns; methods supply verbs."}}},{"domain":"D2","source":"bank","stem":"¿Qué dos formatos de especificación admite Anypoint Platform? (Elige 2)","options":["WSDL únicamente para APIs REST","OpenAPI (OAS)","Markdown sin estructura","Excel","RAML"],"correct":[1,4],"explanation":"RAML 1.0 y OAS 2.0/3.0; también AsyncAPI.","i18n":{"en":{"stem":"Which two spec formats does Anypoint Platform support? (Choose 2)","options":["WSDL only for REST APIs","OpenAPI (OAS)","Unstructured Markdown","Excel","RAML"],"explanation":"RAML 1.0 and OAS 2.0/3.0; also AsyncAPI."}}},{"domain":"D2","source":"bank","stem":"¿Cómo se versiona una API de forma habitual en RAML?","options":["No se versiona","Con la propiedad version y en la baseUri, como /v1","Con un comentario al principio","Cambiando el nombre del archivo de la especificación en cada versión"],"correct":[1],"explanation":"version: v1 y baseUri con {version}.","i18n":{"en":{"stem":"How is an API usually versioned in RAML?","options":["It isn't versioned","With the version property and in the baseUri, like /v1","With a comment at the top","Renaming the spec file on every version"],"explanation":"version: v1 and baseUri with {version}."}}},{"domain":"D2","source":"bank","stem":"¿Qué es un cambio incompatible (breaking change) en una API?","options":["Un cambio que obliga a los consumidores a modificar su código","Corregir una errata en la documentación","Añadir un ejemplo","Añadir un campo opcional nuevo en la respuesta sin cambiar los existentes"],"correct":[0],"explanation":"Quitar campos o cambiar tipos rompe a consumidores.","i18n":{"en":{"stem":"What is a breaking change in an API?","options":["A change forcing consumers to modify their code","Fixing a doc typo","Adding an example","Adding a new optional response field without changing existing ones"],"explanation":"Removing fields or changing types breaks consumers."}}},{"domain":"D2","source":"bank","stem":"¿Qué recomienda la versión semántica para un cambio incompatible?","options":["Incrementar la versión menor solo","Incrementar la versión de parche","Mantener la misma versión","Incrementar la versión mayor"],"correct":[3],"explanation":"MAJOR.MINOR.PATCH.","i18n":{"en":{"stem":"What does semantic versioning recommend for a breaking change?","options":["Increment only the minor version","Increment the patch version","Keep the same version","Increment the major version"],"explanation":"MAJOR.MINOR.PATCH."}}},{"domain":"D2","source":"bank","stem":"¿Qué genera APIkit a partir de una especificación RAML?","options":["Una base de datos","Una política de seguridad","El código del cliente móvil que consumirá la API desde los dispositivos","Flujos de implementación con enrutamiento por recurso y método"],"correct":[3],"explanation":"APIkit crea el router y flujos esqueleto.","i18n":{"en":{"stem":"What does APIkit generate from a RAML spec?","options":["A database","A security policy","The mobile client code that will consume the API from devices","Implementation flows routed by resource and method"],"explanation":"APIkit creates the router and skeleton flows."}}},{"domain":"D2","source":"bank","stem":"¿Qué tipo de RAML se usa para una lista de objetos?","options":["Un array con items del tipo del objeto","Un string con valores separados por comas","Un number","Un boolean"],"correct":[0],"explanation":"type: array, items: Order.","i18n":{"en":{"stem":"Which RAML type is used for a list of objects?","options":["An array with items of the object type","A comma-separated string","A number","A boolean"],"explanation":"type: array, items: Order."}}},{"domain":"D2","source":"bank","stem":"¿Qué propiedad restringe los valores posibles de un string en RAML?","options":["maxItems","enum","uniqueItems","minimum"],"correct":[1],"explanation":"enum lista valores permitidos.","i18n":{"en":{"stem":"Which property restricts a string's possible values in RAML?","options":["maxItems","enum","uniqueItems","minimum"],"explanation":"enum lists allowed values."}}},{"domain":"D2","source":"bank","stem":"¿Qué se publica en Exchange al publicar una especificación desde Design Center?","options":["Los logs de la aplicación","Las credenciales del servidor","La especificación como activo con su documentación y mocking","El código Mule de la implementación listo para desplegar en CloudHub"],"correct":[2],"explanation":"El activo REST API incluye la spec y su portal.","i18n":{"en":{"stem":"What's published to Exchange when publishing a spec from Design Center?","options":["App logs","Server credentials","The spec as an asset with docs and mocking","The Mule implementation code ready to deploy to CloudHub"],"explanation":"The REST API asset includes the spec and its portal."}}},{"domain":"D2","source":"bank","stem":"¿Qué dos elementos describe la respuesta de un método en RAML? (Elige 2)","options":["Nombre del entorno","Configuración del listener","Cuerpo con tipo y ejemplo","Número de workers","Códigos de estado"],"correct":[2,4],"explanation":"responses: 200: body: application/json: type...","i18n":{"en":{"stem":"Which two items does a method's response describe in RAML? (Choose 2)","options":["Environment name","Listener configuration","Body with type and example","Number of workers","Status codes"],"explanation":"responses: 200: body: application/json: type..."}}},{"domain":"D2","source":"bank","stem":"¿Qué indica el código 409 Conflict?","options":["El recurso se movió de forma permanente a otra URL indicada en Location","La petición no está autenticada","El servidor no está disponible","La petición entra en conflicto con el estado actual del recurso"],"correct":[3],"explanation":"Útil, p. ej., al crear un recurso duplicado.","i18n":{"en":{"stem":"What does 409 Conflict indicate?","options":["The resource moved permanently to another URL given in Location","The request is unauthenticated","The server is unavailable","The request conflicts with the resource's current state"],"explanation":"Useful e.g. when creating a duplicate resource."}}},{"domain":"D2","source":"bank","stem":"¿Qué diferencia hay entre 401 y 403?","options":["Son equivalentes","403 es no autenticado y 401 es autenticado pero sin permiso suficiente","401 es no autenticado; 403 es autenticado pero sin permiso","401 es error del servidor"],"correct":[2],"explanation":"Unauthorized vs Forbidden.","i18n":{"en":{"stem":"What's the difference between 401 and 403?","options":["They're equivalent","403 is unauthenticated and 401 is authenticated without enough permission","401 is unauthenticated; 403 is authenticated but not allowed","401 is a server error"],"explanation":"Unauthorized vs Forbidden."}}},{"domain":"D2","source":"bank","stem":"¿Qué permite un recurso anidado en RAML, como /customers/{id}/orders?","options":["Expresar relaciones entre recursos","Duplicar el recurso padre","Cambiar el puerto del listener","Definir la seguridad del servidor HTTP"],"correct":[0],"explanation":"Los recursos anidados modelan jerarquías.","i18n":{"en":{"stem":"What does a nested RAML resource like /customers/{id}/orders allow?","options":["Expressing relationships between resources","Duplicating the parent resource","Changing the listener port","Defining the HTTP server's security"],"explanation":"Nested resources model hierarchies."}}},{"domain":"D2","source":"bank","stem":"¿Qué ventaja tiene diseñar la paginación como trait?","options":["Que se cifren las páginas","Aplicarla de forma consistente en varios métodos","Que se elimine la necesidad de queryParameters","Que la API no devuelva nunca más de un registro por petición"],"correct":[1],"explanation":"Reutilización y consistencia.","i18n":{"en":{"stem":"What's the benefit of designing pagination as a trait?","options":["Pages get encrypted","Applying it consistently across methods","No queryParameters are needed","The API never returns more than one record per request"],"explanation":"Reuse and consistency."}}},{"domain":"D2","source":"bank","stem":"¿Qué tipo de activo de Exchange se crea para un fragmento con tipos de datos reutilizables?","options":["Política","REST API completa","Plantilla de proyecto Mule con tipos","API fragment (RAML fragment)"],"correct":[3],"explanation":"Los fragmentos se referencian desde otras specs.","i18n":{"en":{"stem":"Which Exchange asset is created for a fragment with reusable data types?","options":["Policy","Full REST API","Mule project template with types","API fragment (RAML fragment)"],"explanation":"Fragments are referenced from other specs."}}},{"domain":"D2","source":"bank","stem":"¿Qué indica una especificación RAML con la cabecera #%RAML 1.0 Library?","options":["Que es la especificación principal de la API con todos los recursos definidos","Que el archivo es una librería de tipos, traits u otros elementos","Que es un esquema JSON","Que es un archivo de ejemplo"],"correct":[1],"explanation":"Los fragmentos declaran su tipo en la cabecera.","i18n":{"en":{"stem":"What does a RAML file headed #%RAML 1.0 Library indicate?","options":["It's the main API spec with all resources defined","The file is a library of types, traits or other elements","It's a JSON schema","It's an example file"],"explanation":"Fragments declare their kind in the header."}}},{"domain":"D2","source":"bank","stem":"¿Qué conviene hacer antes de publicar una nueva versión mayor de una API?","options":["Comunicarla a los consumidores y mantener la anterior un tiempo","Retirar la anterior sin aviso","Cambiar el contrato de la versión actual sin versionar ni avisar a nadie","Borrar la documentación"],"correct":[0],"explanation":"Gestión del ciclo de vida y deprecación.","i18n":{"en":{"stem":"What should be done before publishing a new major API version?","options":["Inform consumers and keep the old one for a while","Retire the old one without notice","Changing the current version's contract without versioning or notice","Delete the documentation"],"explanation":"Lifecycle and deprecation management."}}},{"domain":"D2","source":"bank","stem":"¿Qué indica el código 204 No Content?","options":["Éxito sin cuerpo de respuesta","Error del servidor","Recurso creado y devuelto en el cuerpo","Petición mal formada"],"correct":[0],"explanation":"Típico en DELETE exitoso.","i18n":{"en":{"stem":"What does 204 No Content indicate?","options":["Success with no response body","Server error","Resource created and returned in the body","Malformed request"],"explanation":"Typical on successful DELETE."}}},{"domain":"D2","source":"bank","stem":"¿Qué indica el código 503 Service Unavailable?","options":["El recurso pedido no existe en el servidor","El servidor no puede atender temporalmente","El cliente no envió credenciales válidas","La petición se procesó y creó un recurso"],"correct":[1],"explanation":"Suele indicar sobrecarga o mantenimiento.","i18n":{"en":{"stem":"What does 503 Service Unavailable indicate?","options":["The requested resource doesn't exist on the server","The server temporarily can't handle requests","The client sent no valid credentials","The request created a resource"],"explanation":"Usually overload or maintenance."}}},{"domain":"D2","source":"bank","stem":"¿Qué método HTTP se usa para modificar solo algunos campos de un recurso?","options":["PUT con el recurso completo","OPTIONS","PATCH","GET con parámetros de consulta"],"correct":[2],"explanation":"PATCH aplica cambios parciales.","i18n":{"en":{"stem":"Which HTTP method modifies only some fields of a resource?","options":["PUT with the full resource","OPTIONS","PATCH","GET with query parameters"],"explanation":"PATCH applies partial changes."}}},{"domain":"D3","source":"bank","stem":"¿De qué partes se compone un evento Mule en Mule 4?","options":["Mensaje (payload y atributos) y variables","Cabeceras HTTP y cuerpo únicamente","Payload, sesión y propiedades de salida","Solo el payload, sin metadatos"],"correct":[0],"explanation":"El evento contiene el mensaje y las variables.","i18n":{"en":{"stem":"What parts make up a Mule event in Mule 4?","options":["Message (payload and attributes) and variables","Only HTTP headers and body","Payload, session and outbound properties","Only the payload, no metadata"],"explanation":"The event holds the message and variables."}}},{"domain":"D3","source":"bank","stem":"¿Qué contiene attributes tras recibir una petición en un HTTP Listener?","options":["El cuerpo JSON de la petición","La configuración global del listener","Metadatos como cabeceras, queryParams, uriParams y método","Las variables definidas en el flujo"],"correct":[2],"explanation":"El payload es el cuerpo; attributes son metadatos.","i18n":{"en":{"stem":"What does attributes contain after an HTTP Listener receives a request?","options":["The request JSON body","The listener's global config","Metadata like headers, queryParams, uriParams and method","Variables set in the flow"],"explanation":"The payload is the body; attributes are metadata."}}},{"domain":"D3","source":"bank","stem":"¿Cómo se accede a un parámetro de consulta llamado status en DataWeave?","options":["vars.queryParams.status","payload.status","message.status","attributes.queryParams.status"],"correct":[3],"explanation":"Los query params están en attributes.","i18n":{"en":{"stem":"How is a query parameter named status accessed in DataWeave?","options":["vars.queryParams.status","payload.status","message.status","attributes.queryParams.status"],"explanation":"Query params live in attributes."}}},{"domain":"D3","source":"bank","stem":"¿Cómo se accede a un parámetro de URI orderId de /orders/{orderId}?","options":["attributes.queryParams.orderId","vars.orderId sin configurar nada","attributes.uriParams.orderId","payload.orderId"],"correct":[2],"explanation":"Los parámetros de ruta están en uriParams.","i18n":{"en":{"stem":"How is URI parameter orderId from /orders/{orderId} accessed?","options":["attributes.queryParams.orderId","vars.orderId with no setup","attributes.uriParams.orderId","payload.orderId"],"explanation":"Path parameters are in uriParams."}}},{"domain":"D3","source":"bank","stem":"¿Qué componente crea o modifica una variable en el flujo?","options":["Set Variable","Logger","Transform Message sin salidas","Set Payload"],"correct":[0],"explanation":"Set Variable guarda un valor en vars.","i18n":{"en":{"stem":"Which component creates or changes a flow variable?","options":["Set Variable","Logger","Transform Message with no outputs","Set Payload"],"explanation":"Set Variable stores a value in vars."}}},{"domain":"D3","source":"bank","stem":"¿Cómo se lee una variable llamada customer en una expresión?","options":["attributes.customer","flowVars.customer, como en Mule 3","sessionVars.customer","vars.customer"],"correct":[3],"explanation":"En Mule 4 las variables están en vars.","i18n":{"en":{"stem":"How is a variable named customer read in an expression?","options":["attributes.customer","flowVars.customer, as in Mule 3","sessionVars.customer","vars.customer"],"explanation":"In Mule 4 variables live in vars."}}},{"domain":"D3","source":"bank","stem":"¿Qué sintaxis indica una expresión DataWeave en un campo de un componente?","options":["{{ ... }}","#[ ... ]","${ ... }","<% ... %>"],"correct":[1],"explanation":"${} es para propiedades; #[] para expresiones.","i18n":{"en":{"stem":"Which syntax marks a DataWeave expression in a component field?","options":["{{ ... }}","#[ ... ]","${ ... }","<% ... %>"],"explanation":"${} is for properties; #[] for expressions."}}},{"domain":"D3","source":"bank","stem":"¿Qué ocurre con el payload tras una llamada HTTP Request sin variable de destino?","options":["Se concatena con la respuesta","Se reemplaza por la respuesta","Se conserva y la respuesta se descarta","Se guarda en vars.payload"],"correct":[1],"explanation":"Por defecto la salida del conector reemplaza el payload.","i18n":{"en":{"stem":"What happens to the payload after an HTTP Request with no target variable?","options":["It's concatenated with the response","It's replaced by the response","It's kept and the response discarded","It's stored in vars.payload"],"explanation":"By default connector output replaces the payload."}}},{"domain":"D3","source":"bank","stem":"¿Qué permite la propiedad Target Variable de un conector?","options":["Convertir el resultado en XML","Guardar el resultado en una variable sin tocar el payload","Registrar el resultado en los logs","Enviar el resultado a otra aplicación Mule"],"correct":[1],"explanation":"target y targetValue preservan el payload actual.","i18n":{"en":{"stem":"What does a connector's Target Variable property allow?","options":["Converting the result to XML","Storing the result in a variable without touching the payload","Logging the result","Sending the result to another Mule app"],"explanation":"target and targetValue preserve the current payload."}}},{"domain":"D3","source":"bank","stem":"¿Qué indica la propiedad targetValue junto a target?","options":["El tipo MIME de la variable","El nombre del flujo de destino","Qué parte del resultado se guarda en la variable","El tiempo de vida de la variable"],"correct":[2],"explanation":"Por defecto es #[payload]; puede ser #[attributes] u otra expresión.","i18n":{"en":{"stem":"What does targetValue indicate alongside target?","options":["The variable's MIME type","The target flow name","Which part of the result is stored in the variable","The variable's lifetime"],"explanation":"Defaults to #[payload]; can be #[attributes] or another expression."}}},{"domain":"D3","source":"bank","stem":"Tras una llamada HTTP Request, ¿qué contiene attributes?","options":["Las variables del flujo","Siguen siendo los atributos de la petición original recibida por el listener","Los atributos de la petición original del listener","Los metadatos de la respuesta, como statusCode y cabeceras"],"correct":[3],"explanation":"Los attributes se reemplazan con los de la operación.","i18n":{"en":{"stem":"After an HTTP Request, what does attributes contain?","options":["Flow variables","Still the original request attributes received by the listener","The original listener request attributes","Response metadata like statusCode and headers"],"explanation":"Attributes are replaced with the operation's."}}},{"domain":"D3","source":"bank","stem":"¿Cómo se conservan los atributos de la petición original para usarlos después de otra llamada?","options":["Usando sessionVars","Guardándolos en una variable antes de la llamada","Leyéndolos del Logger","No hace falta: los attributes originales siempre se mantienen"],"correct":[1],"explanation":"Las operaciones reemplazan attributes; las variables persisten.","i18n":{"en":{"stem":"How are the original request attributes kept for use after another call?","options":["Using sessionVars","Store them in a variable before the call","Reading them from the Logger","Not needed: original attributes always persist"],"explanation":"Operations replace attributes; variables persist."}}},{"domain":"D3","source":"bank","stem":"¿Qué dos componentes modifican directamente el mensaje? (Elige 2)","options":["Choice sin rutas","Set Payload","Transform Message","Logger","Flow Reference sin lógica"],"correct":[1,2],"explanation":"Set Payload y Transform Message cambian payload (y atributos/variables en Transform).","i18n":{"en":{"stem":"Which two components directly modify the message? (Choose 2)","options":["Choice with no routes","Set Payload","Transform Message","Logger","Flow Reference with no logic"],"explanation":"Set Payload and Transform Message change the payload (and attributes/vars in Transform)."}}},{"domain":"D3","source":"bank","stem":"¿Qué puede generar un Transform Message además del payload?","options":["Nuevos flujos","Configuraciones globales","Variables y atributos","Propiedades del archivo YAML"],"correct":[2],"explanation":"Transform Message admite varias salidas.","i18n":{"en":{"stem":"What can Transform Message output besides the payload?","options":["New flows","Global configurations","Variables and attributes","YAML file properties"],"explanation":"Transform Message supports multiple outputs."}}},{"domain":"D3","source":"bank","stem":"¿Qué componente elimina una variable?","options":["Remove Variable","Flow Reference","Set Variable con valor null obligatoriamente","Logger"],"correct":[0],"explanation":"Remove Variable borra la variable del evento.","i18n":{"en":{"stem":"Which component removes a variable?","options":["Remove Variable","Flow Reference","Set Variable with null mandatorily","Logger"],"explanation":"Remove Variable deletes it from the event."}}},{"domain":"D3","source":"bank","stem":"¿Qué registra el componente Logger?","options":["Las métricas de CPU del worker","El payload en una base de datos","El mensaje o la expresión configurada en el log","Las peticiones y respuestas en Anypoint MQ para poder reenviarlas después"],"correct":[2],"explanation":"Logger escribe en el log con un nivel.","i18n":{"en":{"stem":"What does the Logger component record?","options":["Worker CPU metrics","The payload in a database","The configured message or expression in the log","Requests and responses in Anypoint MQ so they can be replayed later"],"explanation":"Logger writes to the log at a level."}}},{"domain":"D3","source":"bank","stem":"¿Qué nivel de Logger se usa por defecto?","options":["ERROR","DEBUG","INFO","TRACE"],"correct":[2],"explanation":"El nivel por defecto es INFO.","i18n":{"en":{"stem":"Which Logger level is the default?","options":["ERROR","DEBUG","INFO","TRACE"],"explanation":"Default level is INFO."}}},{"domain":"D3","source":"bank","stem":"¿Qué ocurre con las variables al llamar a otro flujo con Flow Reference?","options":["Solo se pasan si son de tipo String","El flujo llamado las ve y puede modificarlas","Se pierden al entrar en el otro flujo","Se copian como atributos y el flujo llamado no puede modificarlas"],"correct":[1],"explanation":"Flow Reference comparte el evento completo.","i18n":{"en":{"stem":"What happens to variables when calling another flow with Flow Reference?","options":["They pass only if String","The called flow sees and can change them","They're lost entering the other flow","They're copied as attributes and the called flow can't change them"],"explanation":"Flow Reference shares the full event."}}},{"domain":"D3","source":"bank","stem":"¿Qué ocurre con las variables al llamar a otra aplicación por HTTP?","options":["Se envían en el cuerpo junto al payload","Se comparten por la memoria del worker con la otra aplicación desplegada","No viajan: solo se envía lo que va en la petición","Se envían automáticamente como cabeceras"],"correct":[2],"explanation":"Las variables son locales al evento de la app.","i18n":{"en":{"stem":"What happens to variables when calling another app over HTTP?","options":["They're sent in the body with the payload","They're shared via worker memory with the other deployed app","They don't travel: only what's in the request is sent","They're auto-sent as headers"],"explanation":"Variables are local to the app's event."}}},{"domain":"D3","source":"bank","stem":"¿Cómo se obtiene el método HTTP de la petición recibida?","options":["vars.method","payload.method","attributes.method","attributes.queryParams.method"],"correct":[2],"explanation":"HttpRequestAttributes incluye method.","i18n":{"en":{"stem":"How is the received request's HTTP method obtained?","options":["vars.method","payload.method","attributes.method","attributes.queryParams.method"],"explanation":"HttpRequestAttributes includes method."}}},{"domain":"D3","source":"bank","stem":"¿Cómo se lee la cabecera Authorization de una petición recibida?","options":["payload.headers.Authorization","message.authorization","vars.headers.authorization","attributes.headers.authorization"],"correct":[3],"explanation":"Las cabeceras se normalizan en minúsculas.","i18n":{"en":{"stem":"How is the Authorization header of a received request read?","options":["payload.headers.Authorization","message.authorization","vars.headers.authorization","attributes.headers.authorization"],"explanation":"Headers are lowercased."}}},{"domain":"D3","source":"bank","stem":"¿Qué devuelve el HTTP Listener como respuesta por defecto?","options":["Los atributos de la petición","Las variables del flujo en JSON","Siempre un cuerpo vacío","El payload final del flujo"],"correct":[3],"explanation":"La respuesta usa el payload al final del flujo.","i18n":{"en":{"stem":"What does the HTTP Listener return as the default response?","options":["The request attributes","Flow variables as JSON","Always an empty body","The flow's final payload"],"explanation":"The response uses the payload at the end of the flow."}}},{"domain":"D3","source":"bank","stem":"¿Dónde se configura el código de estado de la respuesta del listener?","options":["En la sección Responses del HTTP Listener","En el archivo pom.xml","En una variable llamada status sin más","En el Logger"],"correct":[0],"explanation":"statusCode se define en la respuesta (y en Error Response).","i18n":{"en":{"stem":"Where is the listener response status code configured?","options":["In the HTTP Listener's Responses section","In pom.xml","In a plain variable named status","In the Logger"],"explanation":"statusCode is set in the response (and Error Response)."}}},{"domain":"D3","source":"bank","stem":"¿Qué tipo MIME tiene el payload tras un Transform Message con output application/json?","options":["text/plain siempre","application/java","application/json","El mismo que la entrada"],"correct":[2],"explanation":"El output define el formato.","i18n":{"en":{"stem":"What MIME type does the payload have after Transform Message with output application/json?","options":["Always text/plain","application/java","application/json","Same as the input"],"explanation":"The output defines the format."}}},{"domain":"D3","source":"bank","stem":"¿Qué indica que los eventos Mule sean inmutables en Mule 4?","options":["Que no se puede cambiar el payload nunca","Que el flujo no puede tener más de un procesador","Cada procesador produce un evento nuevo en lugar de modificar el anterior","Que las variables no se pueden crear"],"correct":[2],"explanation":"La inmutabilidad facilita el procesamiento concurrente.","i18n":{"en":{"stem":"What does Mule 4 event immutability mean?","options":["The payload can never change","A flow can't have more than one processor","Each processor produces a new event instead of modifying the old","Variables can't be created"],"explanation":"Immutability eases concurrent processing."}}},{"domain":"D3","source":"bank","stem":"¿Qué dos formas hay de establecer el payload a un valor fijo? (Elige 2)","options":["Transform Message","Set Payload","Remove Variable","Logger","Set Variable"],"correct":[0,1],"explanation":"Ambas pueden fijar el payload.","i18n":{"en":{"stem":"Which two ways set the payload to a fixed value? (Choose 2)","options":["Transform Message","Set Payload","Remove Variable","Logger","Set Variable"],"explanation":"Both can set the payload."}}},{"domain":"D3","source":"bank","stem":"¿Qué devuelve la expresión #[payload] si el payload es un stream ya consumido sin repetición?","options":["Puede fallar o estar vacío","Siempre el contenido completo","Un error de sintaxis","Las variables"],"correct":[0],"explanation":"Los streams repetibles (por defecto) evitan este problema.","i18n":{"en":{"stem":"What does #[payload] return if it's a non-repeatable already-consumed stream?","options":["It may fail or be empty","Always the full content","A syntax error","The variables"],"explanation":"Repeatable streams (default) avoid this."}}},{"domain":"D3","source":"bank","stem":"¿Qué estrategia de streaming usa Mule 4 por defecto?","options":["Solo en memoria sin límite","Sin streaming","Repetible en memoria/archivo","No repetible"],"correct":[2],"explanation":"Repeatable file-store stream es el defecto en Mule EE.","i18n":{"en":{"stem":"Which streaming strategy does Mule 4 use by default?","options":["In-memory only without limit","No streaming","Repeatable (memory/file)","Non-repeatable"],"explanation":"Repeatable file-store stream is the EE default."}}},{"domain":"D3","source":"bank","stem":"¿Cómo se accede al código de estado de la respuesta tras un HTTP Request?","options":["payload.statusCode","vars.statusCode sin configurar","error.statusCode","attributes.statusCode"],"correct":[3],"explanation":"HttpResponseAttributes incluye statusCode.","i18n":{"en":{"stem":"How is the response status code accessed after an HTTP Request?","options":["payload.statusCode","vars.statusCode without setup","error.statusCode","attributes.statusCode"],"explanation":"HttpResponseAttributes includes statusCode."}}},{"domain":"D3","source":"bank","stem":"¿Qué tipo de dato tienen las variables en Mule 4?","options":["Solo JSON, porque las variables se serializan siempre en ese formato","Solo números","Cualquier tipo, incluidos objetos y streams","Solo String"],"correct":[2],"explanation":"Las variables pueden contener cualquier valor.","i18n":{"en":{"stem":"What data type can Mule 4 variables hold?","options":["Only JSON, since variables are always serialized in that format","Numbers only","Any type, including objects and streams","String only"],"explanation":"Variables can hold any value."}}},{"domain":"D3","source":"bank","stem":"¿Qué expresión comprueba si un parámetro de consulta existe?","options":["payload.status exists","attributes.queryParams.status != null","#[status]","vars.status is defined"],"correct":[1],"explanation":"Comparar con null o usar isEmpty.","i18n":{"en":{"stem":"Which expression checks whether a query parameter exists?","options":["payload.status exists","attributes.queryParams.status != null","#[status]","vars.status is defined"],"explanation":"Compare with null or use isEmpty."}}},{"domain":"D3","source":"bank","stem":"¿Para qué sirve el operador default en DataWeave, como vars.x default 0?","options":["Usar un valor alternativo si la expresión es null","Borrar la variable","Convertir el valor a número","Lanzar un error si es null"],"correct":[0],"explanation":"default proporciona valores por defecto.","i18n":{"en":{"stem":"What is DataWeave's default operator for, as in vars.x default 0?","options":["Using a fallback if the expression is null","Deleting the variable","Converting to number","Throwing if null"],"explanation":"default provides fallback values."}}},{"domain":"D3","source":"bank","stem":"¿Qué ventaja tiene guardar un valor en una variable en lugar de en el payload?","options":["Que se cifra","Que se envía automáticamente al cliente","Que persiste entre ejecuciones","Conservarlo mientras el payload cambia en pasos posteriores"],"correct":[3],"explanation":"Las variables sobreviven a cambios de payload.","i18n":{"en":{"stem":"What's the benefit of storing a value in a variable rather than the payload?","options":["It's encrypted","It's auto-sent to the client","It persists across executions","Keeping it while the payload changes later"],"explanation":"Variables survive payload changes."}}},{"domain":"D3","source":"bank","stem":"¿Persisten las variables entre dos ejecuciones distintas del mismo flujo?","options":["No: cada evento tiene sus propias variables","Solo si son de tipo String","Sí, si la aplicación está desplegada en CloudHub con un solo worker","Sí, siempre se comparten"],"correct":[0],"explanation":"Para persistir se usa Object Store.","i18n":{"en":{"stem":"Do variables persist between two separate executions of the same flow?","options":["No: each event has its own variables","Only if String","Yes, if the app is deployed on CloudHub with a single worker","Yes, always shared"],"explanation":"Use Object Store to persist."}}},{"domain":"D3","source":"bank","stem":"¿Qué dos elementos forman parte de attributes en un File Read? (Elige 2)","options":["Nombre del archivo","Configuración global","Variables del flujo","Contenido del archivo","Tamaño o fecha de modificación"],"correct":[0,4],"explanation":"FileAttributes contiene metadatos del archivo.","i18n":{"en":{"stem":"Which two items are in attributes after a File Read? (Choose 2)","options":["File name","Global config","Flow variables","File content","Size or modification date"],"explanation":"FileAttributes holds file metadata."}}},{"domain":"D3","source":"bank","stem":"¿Qué devuelve la expresión payload.items[0].price?","options":["El precio del último elemento, porque los índices empiezan por el final","La suma de precios","El precio del primer elemento del array items","El precio del último elemento"],"correct":[2],"explanation":"Los índices empiezan en 0.","i18n":{"en":{"stem":"What does payload.items[0].price return?","options":["The last element's price, since indexes start from the end","The sum of prices","The first items element's price","The last element's price"],"explanation":"Indexes start at 0."}}},{"domain":"D3","source":"bank","stem":"¿Qué selector de DataWeave devuelve todos los valores de una clave en un array de objetos, como payload.*name?","options":["El selector de atributos XML","El selector de índice","El selector multivalor","El selector de rango"],"correct":[2],"explanation":".* devuelve todos los valores coincidentes.","i18n":{"en":{"stem":"Which DataWeave selector returns all values of a key in an array of objects, like payload.*name?","options":["XML attribute selector","Index selector","Multi-value selector","Range selector"],"explanation":".* returns all matching values."}}},{"domain":"D3","source":"bank","stem":"¿Cómo se accede a un atributo XML id de un elemento order en DataWeave?","options":["payload.order.@id","payload.order.id","payload.order[id]","payload.@order.id"],"correct":[0],"explanation":"@ selecciona atributos XML.","i18n":{"en":{"stem":"How is the XML attribute id of an order element accessed in DataWeave?","options":["payload.order.@id","payload.order.id","payload.order[id]","payload.@order.id"],"explanation":"@ selects XML attributes."}}},{"domain":"D3","source":"bank","stem":"¿Qué hace el componente Parse Template?","options":["Genera texto a partir de una plantilla con expresiones","Convierte XML a CSV","Valida un esquema JSON","Envía correos electrónicos con el contenido de una plantilla de Marketing Cloud"],"correct":[0],"explanation":"Rellena plantillas (p. ej. HTML) con expresiones.","i18n":{"en":{"stem":"What does the Parse Template component do?","options":["Generates text from a template with expressions","Converts XML to CSV","Validates a JSON schema","Sends emails with a Marketing Cloud template's content"],"explanation":"Fills templates (e.g. HTML) with expressions."}}},{"domain":"D3","source":"bank","stem":"¿Qué ocurre con el payload al pasar por un Logger?","options":["Se guarda en una variable","Se convierte en texto","No cambia","Se vacía"],"correct":[2],"explanation":"Logger no modifica el evento.","i18n":{"en":{"stem":"What happens to the payload passing through a Logger?","options":["It's saved in a variable","It becomes text","It doesn't change","It's emptied"],"explanation":"Logger doesn't modify the event."}}},{"domain":"D3","source":"bank","stem":"¿Qué dos expresiones son válidas para concatenar cadenas en DataWeave? (Elige 2)","options":["\"Hola $(vars.name)\"","\"Hola \" ++ vars.name","concat sin argumentos","\"Hola \" + vars.name en DataWeave 2","vars.name & \"Hola\""],"correct":[0,1],"explanation":"++ y la interpolación $( ) concatenan.","i18n":{"en":{"stem":"Which two expressions concatenate strings in DataWeave? (Choose 2)","options":["\"Hello $(vars.name)\"","\"Hello \" ++ vars.name","concat with no args","\"Hello \" + vars.name in DataWeave 2","vars.name & \"Hello\""],"explanation":"++ and $( ) interpolation concatenate."}}},{"domain":"D3","source":"bank","stem":"¿Qué devuelve sizeOf(payload) si el payload es un array de 3 elementos?","options":["0","Un error","El tamaño en bytes","3"],"correct":[3],"explanation":"sizeOf cuenta elementos.","i18n":{"en":{"stem":"What does sizeOf(payload) return if the payload is a 3-element array?","options":["0","An error","Size in bytes","3"],"explanation":"sizeOf counts elements."}}},{"domain":"D3","source":"bank","stem":"¿Qué expresión devuelve la fecha y hora actuales en DataWeave?","options":["now()","Date.now()","currentDate","today().time"],"correct":[0],"explanation":"now() devuelve DateTime.","i18n":{"en":{"stem":"Which expression returns the current date-time in DataWeave?","options":["now()","Date.now()","currentDate","today().time"],"explanation":"now() returns DateTime."}}},{"domain":"D3","source":"bank","stem":"¿Qué efecto tiene usar Set Payload con un valor JSON y MIME application/json?","options":["Se convierte siempre en objeto Java","Se guarda en disco como archivo JSON en el directorio de la aplicación","El payload se trata como JSON en pasos posteriores","Se envía a otra app"],"correct":[2],"explanation":"El tipo MIME guía la lectura.","i18n":{"en":{"stem":"What does Set Payload with JSON and MIME application/json do?","options":["It always becomes a Java object","It's saved to disk as a JSON file in the app directory","The payload is treated as JSON downstream","It's sent to another app"],"explanation":"The MIME type guides parsing."}}},{"domain":"D3","source":"bank","stem":"¿Dónde se ve el contenido del evento al depurar en Anypoint Studio?","options":["En la vista Mule Debugger","En el archivo pom.xml","En Runtime Manager","En Exchange"],"correct":[0],"explanation":"El depurador muestra payload, attributes y vars.","i18n":{"en":{"stem":"Where is event content seen while debugging in Anypoint Studio?","options":["In the Mule Debugger view","In pom.xml","In Runtime Manager","In Exchange"],"explanation":"The debugger shows payload, attributes and vars."}}},{"domain":"D3","source":"bank","stem":"¿Qué devuelve attributes.requestPath en un HTTP Listener?","options":["El puerto","La IP del servidor","La ruta de la petición recibida","El cuerpo de la petición"],"correct":[2],"explanation":"requestPath, requestUri, listenerPath son atributos.","i18n":{"en":{"stem":"What does attributes.requestPath return in an HTTP Listener?","options":["Port","Server IP","The received request path","The request body"],"explanation":"requestPath, requestUri and listenerPath are attributes."}}},{"domain":"D3","source":"bank","stem":"¿Qué dos acciones conservan el payload original mientras se llama a un servicio externo? (Elige 2)","options":["Cambiar el MIME","Borrar attributes","Usar target en el HTTP Request","Usar Set Payload después de la llamada","Guardar el payload en una variable antes"],"correct":[2,4],"explanation":"Variables y target preservan datos.","i18n":{"en":{"stem":"Which two actions keep the original payload while calling an external service? (Choose 2)","options":["Change the MIME","Delete attributes","Use target on the HTTP Request","Use Set Payload after the call","Save the payload to a variable first"],"explanation":"Variables and target preserve data."}}},{"domain":"D3","source":"bank","stem":"¿Qué ocurre si se lee vars.x y la variable no existe?","options":["Crea la variable con valor 0","Devuelve null","Devuelve una cadena vacía","Lanza siempre un error de compilación"],"correct":[1],"explanation":"Variables inexistentes son null.","i18n":{"en":{"stem":"What happens reading vars.x when the variable doesn't exist?","options":["Creates it with 0","It returns null","An empty string","Always a compile error"],"explanation":"Missing variables are null."}}},{"domain":"D3","source":"bank","stem":"¿Qué componente permite ejecutar un script DataWeave guardado en un archivo .dwl?","options":["Logger con la ruta del archivo","Set Variable con la ruta","Transform Message referenciando el archivo","Flow Reference al archivo"],"correct":[2],"explanation":"Transform puede usar resource=\"*.dwl\".","i18n":{"en":{"stem":"Which component runs a DataWeave script saved in a .dwl file?","options":["Logger with the file path","Set Variable with the path","Transform Message referencing the file","Flow Reference to the file"],"explanation":"Transform can use resource=\"*.dwl\"."}}},{"domain":"D3","source":"bank","stem":"¿Qué expresión convierte un valor a número en DataWeave?","options":["Number(vars.x)","parseInt(vars.x)","vars.x as Number","vars.x.toNumber()"],"correct":[2],"explanation":"as Type hace coerción.","i18n":{"en":{"stem":"Which expression converts a value to number in DataWeave?","options":["Number(vars.x)","parseInt(vars.x)","vars.x as Number","vars.x.toNumber()"],"explanation":"as Type coerces."}}},{"domain":"D4","source":"bank","stem":"¿Qué diferencia hay entre un flujo y un subflujo?","options":["El subflujo tiene su propio HTTP Listener","No hay diferencia: subflujo es solo el nombre antiguo de flujo en Mule 3","El subflujo no tiene origen ni estrategia de errores propia","El flujo no puede llamarse con Flow Reference"],"correct":[2],"explanation":"Los subflujos se ejecutan síncronamente y heredan el manejo de errores.","i18n":{"en":{"stem":"What's the difference between a flow and a subflow?","options":["A subflow has its own HTTP Listener","No difference: subflow is just Mule 3's old name for flow","A subflow has no source and no own error strategy","A flow can't be called with Flow Reference"],"explanation":"Subflows run synchronously and inherit error handling."}}},{"domain":"D4","source":"bank","stem":"¿Qué es un flujo privado (private flow)?","options":["Un flujo que solo pueden ver los administradores","Un flujo con HTTP Listener en un puerto interno","Un flujo sin origen que se invoca con Flow Reference y tiene su propio manejo de errores","Un flujo cifrado"],"correct":[2],"explanation":"A diferencia del subflujo, puede tener error handler.","i18n":{"en":{"stem":"What is a private flow?","options":["A flow only admins can see","A flow with an HTTP Listener on an internal port","A sourceless flow invoked with Flow Reference with its own error handling","An encrypted flow"],"explanation":"Unlike a subflow, it can have an error handler."}}},{"domain":"D4","source":"bank","stem":"¿Qué componente invoca otro flujo o subflujo de la misma aplicación?","options":["Flow Reference","HTTP Request a localhost","Logger","VM Publish obligatoriamente"],"correct":[0],"explanation":"Flow Reference llama síncronamente.","i18n":{"en":{"stem":"Which component invokes another flow or subflow in the same app?","options":["Flow Reference","HTTP Request to localhost","Logger","Mandatorily VM Publish"],"explanation":"Flow Reference calls synchronously."}}},{"domain":"D4","source":"bank","stem":"¿Qué es un elemento global (global element)?","options":["Un flujo que se ejecuta al arrancar","Una variable visible en todas las aplicaciones de la organización","Un archivo de log compartido por todos los flujos de la aplicación","Una configuración reutilizable, como la conexión HTTP o de base de datos"],"correct":[3],"explanation":"Los global configs se referencian desde conectores.","i18n":{"en":{"stem":"What is a global element?","options":["A flow that runs at startup","A variable visible in every org app","A log file shared by every flow in the application","A reusable configuration like an HTTP or database connection"],"explanation":"Global configs are referenced by connectors."}}},{"domain":"D4","source":"bank","stem":"¿Qué sintaxis se usa para leer una propiedad de configuración, como el puerto?","options":["${http.port}","vars.http.port","#[http.port]","{{http.port}}"],"correct":[0],"explanation":"Los placeholders de propiedades usan ${}.","i18n":{"en":{"stem":"Which syntax reads a configuration property like the port?","options":["${http.port}","vars.http.port","#[http.port]","{{http.port}}"],"explanation":"Property placeholders use ${}."}}},{"domain":"D4","source":"bank","stem":"¿Qué elemento global carga propiedades desde un archivo YAML o properties?","options":["Logger config","Configuration properties","Database config","HTTP Listener config"],"correct":[1],"explanation":"<configuration-properties file=...>.","i18n":{"en":{"stem":"Which global element loads properties from a YAML or properties file?","options":["Logger config","Configuration properties","Database config","HTTP Listener config"],"explanation":"<configuration-properties file=...>."}}},{"domain":"D4","source":"bank","stem":"¿Cómo se cargan propiedades distintas por entorno (dev, prod)?","options":["Editando el XML antes de cada despliegue","No es posible: hay que generar un JAR distinto para cada entorno de despliegue","Copiando el proyecto para cada entorno","Con un archivo por entorno y una propiedad como ${env} en el nombre"],"correct":[3],"explanation":"P. ej. file=\"config-${env}.yaml\" con env definido al desplegar.","i18n":{"en":{"stem":"How are different properties loaded per environment (dev, prod)?","options":["Editing the XML before each deploy","Not possible: a different JAR must be built for each deployment environment","Copying the project per environment","One file per environment with a property like ${env} in the name"],"explanation":"E.g. file=\"config-${env}.yaml\" with env set at deploy."}}},{"domain":"D4","source":"bank","stem":"¿Qué módulo se usa para cifrar propiedades sensibles como contraseñas?","options":["Logger con nivel DEBUG","Secure Properties (secure-properties)","Object Store","Validation module"],"correct":[1],"explanation":"Se leen con ${secure::clave}.","i18n":{"en":{"stem":"Which module encrypts sensitive properties like passwords?","options":["Logger at DEBUG","Secure Properties (secure-properties)","Object Store","Validation module"],"explanation":"Read with ${secure::key}."}}},{"domain":"D4","source":"bank","stem":"¿Cómo se lee una propiedad cifrada con Secure Properties?","options":["#[secure(db.password)]","${secure::db.password}","vars.secure.db.password","${db.password} sin prefijo"],"correct":[1],"explanation":"El prefijo secure:: descifra.","i18n":{"en":{"stem":"How is a Secure Properties-encrypted property read?","options":["#[secure(db.password)]","${secure::db.password}","vars.secure.db.password","${db.password} with no prefix"],"explanation":"The secure:: prefix decrypts."}}},{"domain":"D4","source":"bank","stem":"¿Dónde conviene pasar la clave de descifrado de propiedades seguras?","options":["Escrita en el archivo YAML del proyecto","Como propiedad en tiempo de despliegue, no en el código","En un comentario del XML","En el nombre del flujo"],"correct":[1],"explanation":"Nunca guardar la clave en el repositorio.","i18n":{"en":{"stem":"Where should the secure property decryption key be passed?","options":["Written in the project's YAML file","As a deploy-time property, not in code","In an XML comment","In the flow name"],"explanation":"Never store the key in the repo."}}},{"domain":"D4","source":"bank","stem":"¿Qué ventaja tiene dividir una aplicación en varios archivos de configuración XML?","options":["Que no hacen falta elementos globales","Organización y mantenimiento más sencillos","Que cada archivo se despliega como una app distinta","Que se ejecutan más rápido"],"correct":[1],"explanation":"Se pueden separar global.xml, flujos por recurso, etc.","i18n":{"en":{"stem":"What's the benefit of splitting an app into several XML config files?","options":["No global elements needed","Easier organization and maintenance","Each file deploys as a separate app","They run faster"],"explanation":"E.g. separate global.xml, flows per resource."}}},{"domain":"D4","source":"bank","stem":"¿Qué archivo describe las dependencias Maven de un proyecto Mule?","options":["mule-artifact.json","config.yaml","log4j2.xml","pom.xml"],"correct":[3],"explanation":"Maven gestiona dependencias y el empaquetado.","i18n":{"en":{"stem":"Which file describes a Mule project's Maven dependencies?","options":["mule-artifact.json","config.yaml","log4j2.xml","pom.xml"],"explanation":"Maven manages dependencies and packaging."}}},{"domain":"D4","source":"bank","stem":"¿Dónde se guardan los archivos de configuración XML de los flujos en un proyecto Mule?","options":["src/test/java","src/main/mule","target/","src/main/resources"],"correct":[1],"explanation":"resources contiene propiedades, DWL, etc.","i18n":{"en":{"stem":"Where are flow XML config files stored in a Mule project?","options":["src/test/java","src/main/mule","target/","src/main/resources"],"explanation":"resources holds properties, DWL, etc."}}},{"domain":"D4","source":"bank","stem":"¿Qué hace el ámbito Async?","options":["Reintenta los procesadores internos hasta que terminan sin errores","Ejecuta los procesadores en otro hilo sin esperar su resultado","Espera a que todos los procesadores terminen","Ejecuta en paralelo varias rutas y agrega resultados"],"correct":[1],"explanation":"El flujo principal continúa sin esperar.","i18n":{"en":{"stem":"What does the Async scope do?","options":["Retries the inner processors until they finish without errors","Runs processors on another thread without waiting","Waits for all processors to finish","Runs several routes in parallel and aggregates"],"explanation":"The main flow continues without waiting."}}},{"domain":"D4","source":"bank","stem":"¿Qué ocurre con el payload del flujo principal tras un ámbito Async?","options":["Se convierte en un array","Recibe el resultado del Async","Se vacía","Continúa con el payload que tenía antes del Async"],"correct":[3],"explanation":"Los cambios dentro del Async no afectan al flujo principal.","i18n":{"en":{"stem":"What happens to the main flow payload after an Async scope?","options":["It becomes an array","It receives the Async result","It's emptied","It continues with the payload it had before Async"],"explanation":"Changes inside Async don't affect the main flow."}}},{"domain":"D4","source":"bank","stem":"¿Qué dos piezas componen normalmente una aplicación Mule desplegable? (Elige 2)","options":["El portal de Exchange","El clúster de CloudHub","Recursos como propiedades y scripts DataWeave","La base de datos de producción","Archivos de configuración XML"],"correct":[2,4],"explanation":"Se empaqueta como JAR con configuración y recursos.","i18n":{"en":{"stem":"Which two parts usually make up a deployable Mule app? (Choose 2)","options":["The Exchange portal","The CloudHub cluster","Resources like properties and DataWeave scripts","The production database","XML configuration files"],"explanation":"Packaged as a JAR with config and resources."}}},{"domain":"D4","source":"bank","stem":"¿Qué conviene para compartir configuración, como un listener HTTP, entre varias apps en un mismo servidor on-premises?","options":["Un subflujo compartido entre apps","Copiar la configuración en cada app","Una variable global","Un proyecto de dominio (domain project)"],"correct":[3],"explanation":"Los dominios comparten recursos en Mule runtime on-premises.","i18n":{"en":{"stem":"What allows sharing config like an HTTP listener across apps on one on-prem server?","options":["A subflow shared across apps","Copying the config into each app","A global variable","A domain project"],"explanation":"Domains share resources on on-prem runtime."}}},{"domain":"D4","source":"bank","stem":"¿Qué limitación tienen los proyectos de dominio?","options":["No admiten conectores HTTP","Solo admiten una aplicación","Se despliegan a Exchange","No se usan en CloudHub"],"correct":[3],"explanation":"Aplican a despliegues en servidores gestionados (híbridos).","i18n":{"en":{"stem":"What limitation do domain projects have?","options":["They don't support HTTP connectors","They support only one app","They deploy to Exchange","They're not used on CloudHub"],"explanation":"They apply to self-managed (hybrid) servers."}}},{"domain":"D4","source":"bank","stem":"¿Qué ventaja tiene usar un subflujo para lógica común?","options":["Reutilizarla desde varios flujos","Ejecutarla de forma asíncrona","Exponerla como API","Darle su propio manejo de errores"],"correct":[0],"explanation":"Reutilización sin sobrecarga.","i18n":{"en":{"stem":"What's the benefit of a subflow for shared logic?","options":["Reusing it from several flows","Running it asynchronously","Exposing it as an API","Giving it its own error handling"],"explanation":"Reuse with no overhead."}}},{"domain":"D4","source":"bank","stem":"¿Qué componente permite que dos flujos de la misma app se comuniquen de forma asíncrona con colas?","options":["Logger","Flow Reference","VM connector","HTTP Request a localhost obligatoriamente"],"correct":[2],"explanation":"VM publica y consume en colas internas.","i18n":{"en":{"stem":"Which component lets two flows in the same app communicate asynchronously via queues?","options":["Logger","Flow Reference","VM connector","Mandatorily HTTP Request to localhost"],"explanation":"VM publishes and consumes on internal queues."}}},{"domain":"D4","source":"bank","stem":"¿Qué indica el atributo name de un flujo?","options":["El identificador usado para referenciarlo","El nombre del desarrollador que creó el flujo en Anypoint Studio","El puerto en que escucha","La versión de la app"],"correct":[0],"explanation":"Flow Reference usa ese nombre.","i18n":{"en":{"stem":"What does a flow's name attribute indicate?","options":["The identifier used to reference it","The name of the developer who created the flow in Studio","The listening port","The app version"],"explanation":"Flow Reference uses that name."}}},{"domain":"D4","source":"bank","stem":"¿Qué recomienda MuleSoft para organizar una implementación con APIkit?","options":["Flujos por recurso y método generados por APIkit, más flujos de implementación separados","No usar subflujos","Un archivo XML por cada procesador","Todo en un único flujo gigante"],"correct":[0],"explanation":"Separar interfaz e implementación.","i18n":{"en":{"stem":"What does MuleSoft recommend for organizing an APIkit implementation?","options":["APIkit-generated flows per resource and method, plus separate implementation flows","No subflows","One XML file per processor","Everything in one huge flow"],"explanation":"Separate interface and implementation."}}},{"domain":"D4","source":"bank","stem":"¿Qué tipo de propiedades tienen prioridad: las del archivo o las pasadas al desplegar?","options":["Las del pom.xml","Las pasadas al desplegar (por ejemplo en Runtime Manager)","Las del archivo YAML siempre","Las del log4j2.xml"],"correct":[1],"explanation":"Las propiedades de despliegue sobrescriben las del archivo.","i18n":{"en":{"stem":"Which properties take priority: file ones or deploy-time ones?","options":["pom.xml's","Deploy-time ones (e.g. in Runtime Manager)","Always the YAML file's","log4j2.xml's"],"explanation":"Deploy properties override file ones."}}},{"domain":"D4","source":"bank","stem":"¿Qué dos ventajas aporta externalizar URLs y credenciales a propiedades? (Elige 2)","options":["Cambiar de entorno sin modificar el código","Que se publique en Exchange","Que no haga falta probar","Que la app arranque más rápido","Mantener secretos fuera de los flujos"],"correct":[0,4],"explanation":"Portabilidad y seguridad.","i18n":{"en":{"stem":"Which two benefits come from externalizing URLs and credentials to properties? (Choose 2)","options":["Switching environments without code changes","Publishing to Exchange","No testing needed","Faster app startup","Keeping secrets out of flows"],"explanation":"Portability and security."}}},{"domain":"D4","source":"bank","stem":"¿Qué archivo define metadatos del artefacto como la versión mínima de Mule?","options":["mule-artifact.json","log4j2.xml","application.yaml","pom.xml solamente"],"correct":[0],"explanation":"mule-artifact.json describe el artefacto.","i18n":{"en":{"stem":"Which file defines artifact metadata like the minimum Mule version?","options":["mule-artifact.json","log4j2.xml","application.yaml","Only pom.xml"],"explanation":"mule-artifact.json describes the artifact."}}},{"domain":"D4","source":"bank","stem":"¿Qué conviene si un flujo crece demasiado y es difícil de leer?","options":["Eliminar el manejo de errores","Cambiar el nombre","Duplicarlo en otro archivo","Extraer partes a subflujos o flujos privados"],"correct":[3],"explanation":"Modularidad.","i18n":{"en":{"stem":"What to do if a flow grows too big to read?","options":["Remove error handling","Rename it","Duplicate it in another file","Extract parts into subflows or private flows"],"explanation":"Modularity."}}},{"domain":"D4","source":"bank","stem":"¿Cuándo usar un flujo privado en lugar de un subflujo?","options":["Nunca: los subflujos siempre son preferibles porque admiten manejo de errores","Cuando la lógica necesita su propio manejo de errores","Cuando necesita un HTTP Listener","Cuando se quiere exponer como API"],"correct":[1],"explanation":"Los private flows pueden tener error handler.","i18n":{"en":{"stem":"When to use a private flow instead of a subflow?","options":["Never: subflows are always preferable since they support error handling","When the logic needs its own error handling","When it needs an HTTP Listener","When exposing it as an API"],"explanation":"Private flows can have an error handler."}}},{"domain":"D4","source":"bank","stem":"¿Qué se recomienda guardar en un archivo global.xml?","options":["Todos los flujos de negocio","Elementos globales y propiedades","Los tests MUnit","Las especificaciones RAML"],"correct":[1],"explanation":"Centralizar configuraciones.","i18n":{"en":{"stem":"What's recommended to keep in global.xml?","options":["All business flows","Global elements and properties","MUnit tests","RAML specs"],"explanation":"Centralize configurations."}}},{"domain":"D4","source":"bank","stem":"¿Qué indica la propiedad mule.env en muchos proyectos?","options":["La versión de Java","El entorno activo para elegir el archivo de propiedades","El puerto del listener","El usuario de despliegue"],"correct":[1],"explanation":"Convención habitual para propiedades por entorno.","i18n":{"en":{"stem":"What does the mule.env property often indicate?","options":["The Java version","The active environment to pick the properties file","The listener port","The deploy user"],"explanation":"A common per-environment convention."}}},{"domain":"D4","source":"bank","stem":"¿Qué ocurre con los errores dentro de un ámbito Async?","options":["No se propagan al flujo principal","Se devuelven al cliente HTTP","Se ignoran sin registrar","Detienen siempre el flujo principal"],"correct":[0],"explanation":"El Async se ejecuta de forma independiente.","i18n":{"en":{"stem":"What happens to errors inside an Async scope?","options":["They don't propagate to the main flow","They're returned to the HTTP client","They're ignored unlogged","They always stop the main flow"],"explanation":"Async runs independently."}}},{"domain":"D4","source":"bank","stem":"¿Qué componente de origen (source) inicia un flujo según un intervalo de tiempo?","options":["Logger","Flow Reference","Set Payload","Scheduler"],"correct":[3],"explanation":"Scheduler con frecuencia fija o cron.","i18n":{"en":{"stem":"Which source starts a flow on a time interval?","options":["Logger","Flow Reference","Set Payload","Scheduler"],"explanation":"Scheduler with fixed frequency or cron."}}},{"domain":"D4","source":"bank","stem":"¿Qué dos estrategias de programación admite el Scheduler? (Elige 2)","options":["Expresión cron","Frecuencia fija","Por número de peticiones HTTP","Por usuario conectado","Por tamaño de archivo"],"correct":[0,1],"explanation":"Fixed frequency y cron.","i18n":{"en":{"stem":"Which two scheduling strategies does Scheduler support? (Choose 2)","options":["Cron expression","Fixed frequency","By number of HTTP requests","By connected user","By file size"],"explanation":"Fixed frequency and cron."}}},{"domain":"D4","source":"bank","stem":"¿Qué ocurre si un subflujo lanza un error?","options":["Se ignora y el flujo que lo llamó continúa con el payload anterior","Lo gestiona el manejo de errores del flujo que lo llamó","Se reinicia la app","Lo gestiona su propio error handler"],"correct":[1],"explanation":"Los subflujos no tienen error handler propio.","i18n":{"en":{"stem":"What happens if a subflow throws an error?","options":["It's ignored and the calling flow continues with the prior payload","The calling flow's error handling handles it","The app restarts","Its own error handler handles it"],"explanation":"Subflows have no own error handler."}}},{"domain":"D4","source":"bank","stem":"¿Qué conviene para que una misma app funcione en local y en CloudHub con distinto puerto?","options":["Cambiar el puerto a mano antes de desplegar","Usar ${http.port} y definir el valor por entorno","Usar dos apps","Codificar el puerto 8081 en el listener"],"correct":[1],"explanation":"CloudHub usa ${http.port}.","i18n":{"en":{"stem":"What lets the same app run locally and on CloudHub with different ports?","options":["Change the port by hand before deploying","Use ${http.port} and set it per environment","Use two apps","Hardcode 8081 in the listener"],"explanation":"CloudHub uses ${http.port}."}}},{"domain":"D4","source":"bank","stem":"¿Qué permite el ámbito Cache?","options":["Cifrar el payload","Guardar los logs de la aplicación durante un tiempo configurable","Reutilizar resultados de procesadores costosos","Reintentar errores"],"correct":[2],"explanation":"Cache scope almacena respuestas por clave.","i18n":{"en":{"stem":"What does the Cache scope allow?","options":["Encrypting the payload","Storing app logs for a configurable time","Reusing costly processor results","Retrying errors"],"explanation":"Cache scope stores responses by key."}}},{"domain":"D4","source":"bank","stem":"¿Qué indica un error de \"configuración no encontrada\" en un conector?","options":["El puerto está ocupado","Falta una variable","El payload está vacío","El conector referencia un elemento global inexistente o mal nombrado"],"correct":[3],"explanation":"config-ref debe coincidir con un global element.","i18n":{"en":{"stem":"What does a \"configuration not found\" connector error indicate?","options":["Port in use","Missing variable","Empty payload","The connector references a missing or misnamed global element"],"explanation":"config-ref must match a global element."}}},{"domain":"D4","source":"bank","stem":"¿Qué dos elementos suelen ir en src/main/resources? (Elige 2)","options":["Archivos de propiedades","Flujos XML de Mule","Clases de test MUnit","El archivo pom.xml","Scripts DataWeave .dwl"],"correct":[0,4],"explanation":"Recursos de la app.","i18n":{"en":{"stem":"Which two items usually go in src/main/resources? (Choose 2)","options":["Properties files","Mule XML flows","MUnit test classes","The pom.xml file","DataWeave .dwl scripts"],"explanation":"App resources."}}},{"domain":"D4","source":"bank","stem":"¿Qué ventaja tiene usar flujos privados con VM frente a Flow Reference?","options":["No necesitar configuración","Usar menos memoria siempre","Compartir variables automáticamente","Desacoplar y procesar de forma asíncrona"],"correct":[3],"explanation":"VM desacopla con colas; Flow Reference es síncrono.","i18n":{"en":{"stem":"What's the benefit of private flows via VM over Flow Reference?","options":["No configuration","Always less memory","Automatic variable sharing","Decoupling and async processing"],"explanation":"VM decouples with queues; Flow Reference is sync."}}},{"domain":"D4","source":"bank","stem":"¿Qué indica la opción \"Initial State: stopped\" en un flujo?","options":["El flujo es privado y solo puede invocarse con Flow Reference","El flujo se ejecuta una sola vez","El flujo se borra al desplegar","El flujo no arranca su origen hasta iniciarlo manualmente"],"correct":[3],"explanation":"initialState controla el arranque del source.","i18n":{"en":{"stem":"What does initial state \"stopped\" mean on a flow?","options":["The flow is private and can only be invoked via Flow Reference","The flow runs once","The flow is deleted on deploy","The flow's source won't start until started manually"],"explanation":"initialState controls source startup."}}},{"domain":"D4","source":"bank","stem":"¿Qué conviene en un proyecto Mule para valores que cambian por entorno pero no son secretos?","options":["Escribirlos en los flujos","Propiedades en archivos por entorno","Variables de flujo fijas","Comentarios en el XML que el desarrollador cambia antes de cada despliegue"],"correct":[1],"explanation":"Externalizar configuración.","i18n":{"en":{"stem":"What's advisable for values that change per environment but aren't secrets?","options":["Hardcoding them in flows","Properties in per-environment files","Fixed flow variables","XML comments the developer changes before each deploy"],"explanation":"Externalize configuration."}}},{"domain":"D4","source":"bank","stem":"¿Qué ocurre si dos archivos XML de la app definen un flujo con el mismo nombre?","options":["Se usa el primero","Se combinan en un único flujo con los procesadores de ambos archivos","La aplicación falla al desplegarse","Se ejecutan los dos"],"correct":[2],"explanation":"Los nombres deben ser únicos.","i18n":{"en":{"stem":"What happens if two app XML files define a flow with the same name?","options":["The first is used","They merge into one flow with both files' processors","The app fails to deploy","Both run"],"explanation":"Names must be unique."}}},{"domain":"D4","source":"bank","stem":"¿Qué conviene para reutilizar elementos entre muchos proyectos Mule de distintos equipos?","options":["Usar proyectos de dominio en CloudHub","Publicar plantillas o librerías en Exchange","Copiar los archivos por correo","Duplicar código"],"correct":[1],"explanation":"Exchange como catálogo de activos.","i18n":{"en":{"stem":"What enables reusing elements across many teams' Mule projects?","options":["Using domain projects on CloudHub","Publishing templates or libraries to Exchange","Emailing the files","Duplicating code"],"explanation":"Exchange as the asset catalog."}}},{"domain":"D4","source":"bank","stem":"¿Qué tipo de flujo se recomienda para un proceso nocturno que lee archivos?","options":["Un flujo con HTTP Listener","Un flujo con Scheduler o File On New File como origen","Un ámbito Async dentro de un flujo con HTTP Listener que se llama cada noche","Un subflujo sin origen"],"correct":[1],"explanation":"Orígenes de tiempo o de archivo.","i18n":{"en":{"stem":"Which flow suits a nightly file-reading process?","options":["A flow with HTTP Listener","A flow with Scheduler or File On New File as source","An Async scope inside an HTTP Listener flow called each night","A sourceless subflow"],"explanation":"Time or file sources."}}},{"domain":"D4","source":"bank","stem":"¿Qué indica que un flujo tenga un HTTP Listener como origen?","options":["Se ejecuta al arrancar una vez","Se ejecuta según un horario","Solo puede llamarse con Flow Reference","Se ejecuta al recibir peticiones HTTP"],"correct":[3],"explanation":"El source define el disparador.","i18n":{"en":{"stem":"What does an HTTP Listener source on a flow mean?","options":["It runs once at startup","It runs on a schedule","It can only be called via Flow Reference","It runs when HTTP requests arrive"],"explanation":"The source defines the trigger."}}},{"domain":"D4","source":"bank","stem":"Un equipo quiere que la lógica de cálculo de impuestos se use en tres flujos y tenga su propio manejo de errores. ¿Qué crea?","options":["Un subflujo, porque admite su propio bloque de manejo de errores independiente","Un ámbito Async en cada uno de los tres flujos con la lógica duplicada","Un flujo privado","Un elemento global de configuración con la fórmula de impuestos"],"correct":[2],"explanation":"Los flujos privados se reutilizan y pueden tener error handler.","i18n":{"en":{"stem":"A team wants tax calculation logic used in three flows with its own error handling. What do they build?","options":["A subflow, since it supports its own independent error handling block","An Async scope in each of the three flows with duplicated logic","A private flow","A global config element holding the tax formula"],"explanation":"Private flows are reusable and can have an error handler."}}},{"domain":"D4","source":"bank","stem":"¿Qué ocurre si se usa ${db.url} y la propiedad no existe en ningún archivo ni en el despliegue?","options":["Mule busca la propiedad en Exchange y la descarga","La aplicación falla al arrancar","Se toma el valor de la última aplicación desplegada en el mismo worker","Se usa una cadena vacía y la app arranca con normalidad sin advertencias"],"correct":[1],"explanation":"Los placeholders sin resolver impiden el despliegue.","i18n":{"en":{"stem":"What happens if ${db.url} is used and the property doesn't exist anywhere?","options":["Mule fetches the property from Exchange","The app fails to start","The value of the last app deployed on the same worker is used","An empty string is used and the app starts normally with no warnings"],"explanation":"Unresolved placeholders block deployment."}}},{"domain":"D4","source":"bank","stem":"¿Qué dos riesgos tiene guardar contraseñas en texto plano en un YAML del repositorio? (Elige 2)","options":["Exposición de credenciales a quien acceda al código","Que DataWeave no pueda leer el resto de propiedades del archivo","Que la aplicación no compile en Anypoint Studio por usar texto plano","Que CloudHub rechace cualquier propiedad sin el prefijo secure","Fugas al compartir el proyecto o publicarlo"],"correct":[0,4],"explanation":"Usar Secure Properties o un gestor de secretos.","i18n":{"en":{"stem":"Which two risks come from plain-text passwords in a repo YAML? (Choose 2)","options":["Credential exposure to anyone with code access","DataWeave can't read the file's other properties","The app won't compile in Studio for using plain text","CloudHub rejects any property without the secure prefix","Leaks when sharing or publishing the project"],"explanation":"Use Secure Properties or a secrets manager."}}},{"domain":"D4","source":"bank","stem":"Un flujo con Scheduler procesa un lote y otro lote empieza antes de terminar el anterior. ¿Qué ajuste lo evita?","options":["Cambiar el Scheduler por un HTTP Listener con el mismo intervalo","Subir la frecuencia del Scheduler para que los lotes terminen antes","Limitar la concurrencia del flujo (maxConcurrency = 1)","Añadir un Logger al inicio del flujo para marcar el comienzo"],"correct":[2],"explanation":"maxConcurrency controla ejecuciones simultáneas.","i18n":{"en":{"stem":"A Scheduler flow processes a batch and another starts before the first ends. Which setting prevents it?","options":["Replace the Scheduler with an HTTP Listener at the same interval","Raise the Scheduler frequency so batches finish sooner","Limit flow concurrency (maxConcurrency = 1)","Add a Logger at flow start to mark the beginning"],"explanation":"maxConcurrency controls simultaneous executions."}}},{"domain":"D4","source":"bank","stem":"¿Qué conviene para que la configuración del puerto del HTTP Listener funcione en CloudHub?","options":["Configurar el puerto en el archivo log4j2.xml del proyecto","Usar ${http.port} en el listener","Fijar el puerto 80 en el listener porque CloudHub lo expone directamente","Abrir un puerto propio en la configuración de red del worker"],"correct":[1],"explanation":"CloudHub inyecta http.port (8081).","i18n":{"en":{"stem":"What makes the HTTP Listener port config work on CloudHub?","options":["Set the port in the project's log4j2.xml","Use ${http.port} on the listener","Hardcode port 80 since CloudHub exposes it directly","Open a custom port in the worker's network config"],"explanation":"CloudHub injects http.port (8081)."}}},{"domain":"D4","source":"bank","stem":"Un desarrollador quiere cambiar el endpoint de un servicio externo entre QA y producción sin reempaquetar. ¿Qué hace?","options":["Definir la URL como propiedad y pasarla por entorno","Crear dos versiones de la aplicación con URL distinta","Editar el XML del flujo dentro del JAR desplegado en cada entorno","Leer la URL de una variable que el cliente envía en cada petición"],"correct":[0],"explanation":"Externalizar configuración por entorno.","i18n":{"en":{"stem":"A developer wants to switch an external endpoint between QA and production without repackaging. What do they do?","options":["Define the URL as a property set per environment","Build two app versions with different URLs","Edit the flow XML inside the deployed JAR per environment","Read the URL from a variable the client sends each request"],"explanation":"Externalize per-environment config."}}},{"domain":"D5","source":"bank","stem":"¿Qué hace el APIkit Router?","options":["Aplica políticas de seguridad definidas en API Manager","Convierte la especificación RAML en una especificación OpenAPI","Enruta cada petición al flujo del recurso y método correspondiente","Despliega la API en CloudHub y registra su instancia en API Manager"],"correct":[2],"explanation":"El router valida y dirige según la especificación.","i18n":{"en":{"stem":"What does the APIkit Router do?","options":["Applies API Manager security policies","Converts the RAML spec into an OpenAPI spec","Routes each request to the matching resource and method flow","Deploys the API to CloudHub and registers it in API Manager"],"explanation":"The router validates and dispatches per the spec."}}},{"domain":"D5","source":"bank","stem":"¿Qué valida APIkit automáticamente frente a la especificación?","options":["Parámetros, cabeceras y cuerpo de la petición","El rendimiento de la base de datos usada por la API","La lógica de negocio implementada en cada flujo de recurso","Los permisos del usuario en Access Management"],"correct":[0],"explanation":"Las peticiones inválidas generan errores APIKIT.","i18n":{"en":{"stem":"What does APIkit validate automatically against the spec?","options":["Request parameters, headers and body","The database performance used by the API","The business logic implemented in each resource flow","The user's Access Management permissions"],"explanation":"Invalid requests raise APIKIT errors."}}},{"domain":"D5","source":"bank","stem":"¿Qué genera el scaffolding de APIkit en Anypoint Studio?","options":["La base de datos con tablas para cada recurso de la API","Pruebas de carga para cada endpoint","Un flujo por cada combinación de recurso y método","Un único flujo genérico que hay que dividir manualmente después"],"correct":[2],"explanation":"Se generan flujos como get:\\orders:api-config.","i18n":{"en":{"stem":"What does APIkit scaffolding generate in Anypoint Studio?","options":["A database with tables for each API resource","Load tests for each endpoint","A flow per resource and method combination","A single generic flow to split manually later"],"explanation":"Flows like get:\\orders:api-config are generated."}}},{"domain":"D5","source":"bank","stem":"¿Qué devuelven los flujos generados por APIkit antes de implementarlos?","options":["Los datos reales del sistema de origen","Las respuestas de ejemplo de la especificación","Una respuesta vacía con código 204 en todos los casos","Un error 500 indicando que el flujo no está implementado"],"correct":[1],"explanation":"Los ejemplos del RAML se usan como respuesta inicial.","i18n":{"en":{"stem":"What do APIkit-generated flows return before implementation?","options":["Real data from the source system","The spec's example responses","An empty 204 response in every case","A 500 error saying the flow isn't implemented"],"explanation":"RAML examples are used as the initial response."}}},{"domain":"D5","source":"bank","stem":"¿Qué error lanza APIkit cuando el recurso solicitado no existe en la especificación?","options":["HTTP:CONNECTIVITY con el código de la ruta","APIKIT:NOT_FOUND","APIKIT:BAD_REQUEST, que se usa para cualquier ruta desconocida","MULE:EXPRESSION con el detalle del recurso"],"correct":[1],"explanation":"Se mapea normalmente a 404.","i18n":{"en":{"stem":"Which error does APIkit raise when the requested resource isn't in the spec?","options":["HTTP:CONNECTIVITY with the path code","APIKIT:NOT_FOUND","APIKIT:BAD_REQUEST, used for any unknown path","MULE:EXPRESSION with resource detail"],"explanation":"Usually mapped to 404."}}},{"domain":"D5","source":"bank","stem":"¿Qué error lanza APIkit cuando el método HTTP no está definido para un recurso?","options":["APIKIT:UNSUPPORTED_MEDIA_TYPE","APIKIT:NOT_ACCEPTABLE","APIKIT:METHOD_NOT_ALLOWED","APIKIT:NOT_FOUND para cualquier método no admitido"],"correct":[2],"explanation":"Se mapea a 405.","i18n":{"en":{"stem":"Which error does APIkit raise when the HTTP method isn't defined for a resource?","options":["APIKIT:UNSUPPORTED_MEDIA_TYPE","APIKIT:NOT_ACCEPTABLE","APIKIT:METHOD_NOT_ALLOWED","APIKIT:NOT_FOUND for any unsupported method"],"explanation":"Mapped to 405."}}},{"domain":"D5","source":"bank","stem":"¿Qué error lanza APIkit si el cuerpo no cumple el tipo definido en la especificación?","options":["APIKIT:METHOD_NOT_ALLOWED","MULE:TRANSFORMATION","APIKIT:BAD_REQUEST","APIKIT:NOT_FOUND porque el cuerpo no coincide con ningún recurso"],"correct":[2],"explanation":"Se mapea a 400.","i18n":{"en":{"stem":"Which error does APIkit raise if the body doesn't match the spec type?","options":["APIKIT:METHOD_NOT_ALLOWED","MULE:TRANSFORMATION","APIKIT:BAD_REQUEST","APIKIT:NOT_FOUND since the body matches no resource"],"explanation":"Mapped to 400."}}},{"domain":"D5","source":"bank","stem":"¿Qué error indica que el Content-Type enviado no está admitido?","options":["APIKIT:BAD_REQUEST siempre","HTTP:UNAUTHORIZED","APIKIT:UNSUPPORTED_MEDIA_TYPE","APIKIT:NOT_ACCEPTABLE, que se refiere al Content-Type de la petición"],"correct":[2],"explanation":"415; NOT_ACCEPTABLE (406) se refiere a Accept.","i18n":{"en":{"stem":"Which error indicates the sent Content-Type isn't supported?","options":["Always APIKIT:BAD_REQUEST","HTTP:UNAUTHORIZED","APIKIT:UNSUPPORTED_MEDIA_TYPE","APIKIT:NOT_ACCEPTABLE, which refers to the request Content-Type"],"explanation":"415; NOT_ACCEPTABLE (406) refers to Accept."}}},{"domain":"D5","source":"bank","stem":"¿Dónde se mapean por defecto los errores de APIkit a códigos HTTP en el proyecto generado?","options":["En el archivo pom.xml mediante propiedades de Maven","En API Manager mediante una política de errores","En el manejador de errores del flujo principal de la API","En el archivo RAML en la sección errors"],"correct":[2],"explanation":"El flujo api-main incluye On Error Propagate por tipo APIKIT.","i18n":{"en":{"stem":"Where are APIkit errors mapped to HTTP codes by default in the generated project?","options":["In pom.xml via Maven properties","In API Manager via an error policy","In the main API flow's error handler","In the RAML file's errors section"],"explanation":"The api-main flow includes On Error Propagate per APIKIT type."}}},{"domain":"D5","source":"bank","stem":"¿Qué ofrece la APIkit Console?","options":["Una interfaz para probar la API en ejecución","Un editor de flujos alternativo a Anypoint Studio","Un panel de métricas de rendimiento de producción","Un catálogo de conectores"],"correct":[0],"explanation":"La consola permite enviar peticiones de prueba.","i18n":{"en":{"stem":"What does the APIkit Console offer?","options":["An interface to test the running API","An alternative flow editor to Anypoint Studio","A production performance metrics dashboard","A connector catalog"],"explanation":"The console lets you send test requests."}}},{"domain":"D5","source":"bank","stem":"Tras añadir un recurso nuevo a la especificación, ¿cómo se generan sus flujos?","options":["Regenerando los flujos con APIkit sin borrar los existentes","Escribiendo el XML a mano porque APIkit solo genera una vez","Publicando la especificación en Exchange, que actualiza el proyecto","Borrando el proyecto y creando uno nuevo desde la especificación"],"correct":[0],"explanation":"APIkit añade flujos que faltan.","i18n":{"en":{"stem":"After adding a new resource to the spec, how are its flows generated?","options":["Regenerating flows with APIkit without deleting existing ones","Writing the XML by hand since APIkit only generates once","Publishing the spec to Exchange, which updates the project","Deleting the project and creating a new one from the spec"],"explanation":"APIkit adds missing flows."}}},{"domain":"D5","source":"bank","stem":"¿Qué ventaja tiene implementar la API importando la especificación desde Exchange?","options":["La aplicación se despliega automáticamente en producción","Se crean las políticas de seguridad","No hace falta escribir lógica de negocio","La implementación queda ligada al contrato publicado"],"correct":[3],"explanation":"Se mantiene sincronía con la especificación gestionada.","i18n":{"en":{"stem":"What's the benefit of implementing the API by importing the spec from Exchange?","options":["The app auto-deploys to production","Security policies are created","No business logic is needed","The implementation stays tied to the published contract"],"explanation":"It stays in sync with the managed spec."}}},{"domain":"D5","source":"bank","stem":"¿Qué indica el nombre de flujo get:\\orders\\(orderId):api-config?","options":["Que es un flujo de error para el recurso orders","Que es un subflujo privado para pedidos sin relación con el router","Que gestiona GET sobre /orders/{orderId} con esa configuración de APIkit","Que es un flujo programado que se ejecuta con un Scheduler para los pedidos"],"correct":[2],"explanation":"Convención de nombres de APIkit.","i18n":{"en":{"stem":"What does flow name get:\\orders\\(orderId):api-config indicate?","options":["It's an error flow for the orders resource","It's a private subflow for orders unrelated to the router","It handles GET on /orders/{orderId} with that APIkit config","It's a scheduled flow run by a Scheduler for orders"],"explanation":"APIkit naming convention."}}},{"domain":"D5","source":"bank","stem":"¿Qué dos piezas genera APIkit en el flujo principal de la API? (Elige 2)","options":["El APIkit Router","Un conector de base de datos configurado","Un HTTP Listener","Una política de rate limiting","Un Scheduler nocturno"],"correct":[0,2],"explanation":"Listener + Router + error handling.","i18n":{"en":{"stem":"Which two pieces does APIkit generate in the main API flow? (Choose 2)","options":["The APIkit Router","A configured database connector","An HTTP Listener","A rate-limiting policy","A nightly Scheduler"],"explanation":"Listener + Router + error handling."}}},{"domain":"D5","source":"bank","stem":"¿Qué ocurre si la API recibe un parámetro de consulta obligatorio ausente según el RAML?","options":["APIkit devuelve un error de petición incorrecta","Se usa el valor por defecto de la base de datos","La petición se reenvía a otro recurso similar","El flujo se ejecuta con el parámetro a null sin validación"],"correct":[0],"explanation":"La validación del router lanza BAD_REQUEST.","i18n":{"en":{"stem":"What happens if a RAML-required query parameter is missing?","options":["APIkit returns a bad request error","The database default is used","The request is forwarded to a similar resource","The flow runs with the parameter null unvalidated"],"explanation":"Router validation raises BAD_REQUEST."}}},{"domain":"D5","source":"bank","stem":"¿Qué es el APIkit para SOAP?","options":["Un generador de flujos a partir de un WSDL","Una política de seguridad SOAP","Un conector para llamar a servicios SOAP externos","Un convertidor de SOAP a GraphQL"],"correct":[0],"explanation":"Genera flujos por operación del WSDL.","i18n":{"en":{"stem":"What is APIkit for SOAP?","options":["A flow generator from a WSDL","A SOAP security policy","A connector to call external SOAP services","A SOAP-to-GraphQL converter"],"explanation":"It generates flows per WSDL operation."}}},{"domain":"D5","source":"bank","stem":"¿Qué recomienda MuleSoft para la lógica de negocio en flujos de APIkit?","options":["Poner toda la lógica en el flujo principal junto al router","Implementar la lógica en el archivo RAML","Duplicar la lógica en cada flujo de recurso","Mantener los flujos de recurso finos y delegar en flujos de implementación"],"correct":[3],"explanation":"Separa interfaz e implementación.","i18n":{"en":{"stem":"What does MuleSoft recommend for business logic in APIkit flows?","options":["Put all logic in the main flow with the router","Implement logic in the RAML file","Duplicate logic in each resource flow","Keep resource flows thin and delegate to implementation flows"],"explanation":"It separates interface and implementation."}}},{"domain":"D5","source":"bank","stem":"¿Qué permite el mocking de APIkit en Studio antes de implementar?","options":["Generar automáticamente la lógica de negocio","Conectarse a la base de datos de producción en modo lectura","Devolver ejemplos para que los consumidores prueben","Desplegar la API sin credenciales"],"correct":[2],"explanation":"Los flujos scaffolded responden con ejemplos.","i18n":{"en":{"stem":"What does APIkit mocking in Studio allow before implementation?","options":["Auto-generating business logic","Connecting read-only to the production database","Returning examples for consumers to test","Deploying the API without credentials"],"explanation":"Scaffolded flows respond with examples."}}},{"domain":"D5","source":"bank","stem":"¿Qué error lanza APIkit cuando el cliente pide en Accept un tipo que la API no ofrece?","options":["APIKIT:UNSUPPORTED_MEDIA_TYPE, que se refiere a la cabecera Accept","APIKIT:NOT_ACCEPTABLE","APIKIT:NOT_IMPLEMENTED","APIKIT:BAD_REQUEST"],"correct":[1],"explanation":"406 Not Acceptable.","i18n":{"en":{"stem":"Which error does APIkit raise when Accept asks for an unsupported type?","options":["APIKIT:UNSUPPORTED_MEDIA_TYPE, which refers to Accept","APIKIT:NOT_ACCEPTABLE","APIKIT:NOT_IMPLEMENTED","APIKIT:BAD_REQUEST"],"explanation":"406 Not Acceptable."}}},{"domain":"D5","source":"bank","stem":"¿Qué configuración global necesita el APIkit Router?","options":["Una configuración de APIkit que apunte a la especificación","Una configuración de base de datos con la URL del sistema","Un archivo de propiedades seguras","Una política de API Manager"],"correct":[0],"explanation":"apikit:config con la ruta del RAML.","i18n":{"en":{"stem":"Which global config does the APIkit Router need?","options":["An APIkit config pointing to the spec","A database config with the system URL","A secure properties file","An API Manager policy"],"explanation":"apikit:config with the RAML path."}}},{"domain":"D5","source":"bank","stem":"¿Qué indica la ruta del listener /api/* en el flujo principal de APIkit?","options":["Que la API no tiene recursos","Que todas las peticiones bajo /api llegan al router","Que solo se admite la ruta exacta /api","Que la API está desactivada y solo responde a la ruta exacta /api"],"correct":[1],"explanation":"El comodín captura todas las rutas.","i18n":{"en":{"stem":"What does listener path /api/* in the main APIkit flow indicate?","options":["The API has no resources","All requests under /api reach the router","Only the exact path /api is accepted","The API is disabled and only answers the exact /api path"],"explanation":"The wildcard catches all paths."}}},{"domain":"D5","source":"bank","stem":"¿Qué conviene hacer si la especificación cambia de forma incompatible?","options":["Borrar la versión anterior inmediatamente","Crear una nueva versión mayor de la API e implementación","Ignorar el cambio en la implementación","Cambiar la especificación en caliente y redesplegar sin avisar"],"correct":[1],"explanation":"Versionado para no romper consumidores.","i18n":{"en":{"stem":"What should be done if the spec changes incompatibly?","options":["Delete the old version immediately","Create a new major API version and implementation","Ignore the change in the implementation","Change the spec live and redeploy without notice"],"explanation":"Versioning avoids breaking consumers."}}},{"domain":"D5","source":"bank","stem":"¿Qué dos tipos de especificación puede usar APIkit para REST? (Elige 2)","options":["Un archivo CSV de endpoints","WSDL para recursos REST","RAML","OAS (OpenAPI)","Un esquema XSD sin especificación"],"correct":[2,3],"explanation":"APIkit admite RAML y OAS.","i18n":{"en":{"stem":"Which two spec types can APIkit use for REST? (Choose 2)","options":["A CSV of endpoints","WSDL for REST resources","RAML","OAS (OpenAPI)","An XSD schema with no spec"],"explanation":"APIkit supports RAML and OAS."}}},{"domain":"D5","source":"bank","stem":"¿Qué ocurre con los flujos implementados si se vuelve a generar APIkit?","options":["Se conservan; solo se añaden los que faltan","Se borran todos","Se sobrescriben con ejemplos","Se convierten en subflujos"],"correct":[0],"explanation":"El scaffolding no sobrescribe implementaciones.","i18n":{"en":{"stem":"What happens to implemented flows when APIkit regenerates?","options":["They're kept; only missing ones are added","They're all deleted","They're overwritten with examples","They become subflows"],"explanation":"Scaffolding doesn't overwrite implementations."}}},{"domain":"D5","source":"bank","stem":"¿Qué ventaja tiene la validación de APIkit para la seguridad?","options":["Cifra el tráfico","Oculta la especificación","Rechaza peticiones mal formadas antes de llegar a la lógica","Sustituye a las políticas de autenticación"],"correct":[2],"explanation":"Validación de entrada temprana.","i18n":{"en":{"stem":"What security benefit does APIkit validation give?","options":["Encrypts traffic","Hides the spec","Rejects malformed requests before reaching logic","Replaces authentication policies"],"explanation":"Early input validation."}}},{"domain":"D5","source":"bank","stem":"Un consumidor envía un campo extra no definido en el tipo RAML. ¿Qué sucede por defecto?","options":["Siempre se rechaza con un 500","Depende de si el tipo permite propiedades adicionales","La API se detiene hasta que el administrador revisa el campo extra","Siempre se ignora y se borra el campo"],"correct":[1],"explanation":"additionalProperties controla esto en RAML.","i18n":{"en":{"stem":"A consumer sends an extra field not in the RAML type. What happens by default?","options":["Always rejected with 500","It depends on whether the type allows additional properties","The API stops until an admin reviews the extra field","Always ignored and stripped"],"explanation":"additionalProperties controls this in RAML."}}},{"domain":"D5","source":"bank","stem":"¿Qué conviene probar de una interfaz APIkit antes de implementar la lógica?","options":["Que rutas, métodos y validaciones responden según el contrato","Que el worker tenga 4 vCores","Que exista una política de caché","Que la base de datos tenga índices"],"correct":[0],"explanation":"Validar la interfaz primero.","i18n":{"en":{"stem":"What should be tested in an APIkit interface before implementing logic?","options":["Routes, methods and validations respond per the contract","The worker has 4 vCores","A caching policy exists","The database has indexes"],"explanation":"Validate the interface first."}}},{"domain":"D5","source":"bank","stem":"¿Qué componente transforma el payload a la estructura de la respuesta definida en el RAML?","options":["APIkit Router","HTTP Listener","Transform Message","Logger, configurado con la plantilla de respuesta del RAML"],"correct":[2],"explanation":"DataWeave da forma a la respuesta.","i18n":{"en":{"stem":"Which component shapes the payload into the RAML response structure?","options":["APIkit Router","HTTP Listener","Transform Message","Logger, configured with the RAML response template"],"explanation":"DataWeave shapes the response."}}},{"domain":"D5","source":"bank","stem":"¿Qué indica un 404 devuelto por APIkit para una ruta que sí existe en otra versión?","options":["Falta un permiso del consumidor en Access Management para esa ruta","La versión en la URL no coincide con la especificación desplegada","El recurso está vacío","La base de datos falla"],"correct":[1],"explanation":"La baseUri incluye la versión.","i18n":{"en":{"stem":"What does an APIkit 404 for a path that exists in another version indicate?","options":["The consumer lacks an Access Management permission for that path","The URL version doesn't match the deployed spec","The resource is empty","The database fails"],"explanation":"The baseUri includes the version."}}},{"domain":"D5","source":"bank","stem":"¿Qué genera APIkit a partir de los ejemplos de la especificación en los flujos de recurso?","options":["Un Scheduler","Un Transform Message que devuelve el ejemplo","Un conector de base de datos","Una política"],"correct":[1],"explanation":"Respuesta simulada inicial.","i18n":{"en":{"stem":"What does APIkit generate from spec examples in resource flows?","options":["A Scheduler","A Transform Message returning the example","A database connector","A policy"],"explanation":"An initial mocked response."}}},{"domain":"D5","source":"bank","stem":"¿Qué dos validaciones hace APIkit sobre cabeceras? (Elige 2)","options":["Que el usuario esté en Access Management","Que la cabecera tenga menos de 10 caracteres","Que el cliente esté en la misma red","Presencia de cabeceras obligatorias","Tipo o formato del valor declarado"],"correct":[3,4],"explanation":"Según la declaración en la especificación.","i18n":{"en":{"stem":"Which two header validations does APIkit perform? (Choose 2)","options":["The user being in Access Management","The header being under 10 characters","The client being on the same network","Presence of required headers","Type or format of the declared value"],"explanation":"Per the spec declaration."}}},{"domain":"D5","source":"bank","stem":"¿Qué ventaja tiene separar la especificación en un activo de Exchange y la implementación en el proyecto?","options":["La implementación se genera sola","El proyecto ya no necesita la especificación","Se evita el versionado","Varios equipos pueden consumir y gobernar el contrato"],"correct":[3],"explanation":"El contrato es un activo compartido.","i18n":{"en":{"stem":"What's the benefit of keeping the spec as an Exchange asset and the implementation in the project?","options":["The implementation self-generates","The project no longer needs the spec","Versioning is avoided","Several teams can consume and govern the contract"],"explanation":"The contract is a shared asset."}}},{"domain":"D5","source":"bank","stem":"¿Qué conviene devolver en el cuerpo de un error 400 de la API?","options":["Un mensaje claro y consistente con el detalle del problema","La traza completa de Java del error interno","Las credenciales de la base de datos","Un cuerpo vacío siempre"],"correct":[0],"explanation":"Errores consistentes sin exponer internos.","i18n":{"en":{"stem":"What should a 400 error body contain?","options":["A clear, consistent message with problem detail","The full internal Java stack trace","Database credentials","Always an empty body"],"explanation":"Consistent errors without exposing internals."}}},{"domain":"D5","source":"bank","stem":"¿Qué indica el flujo api-console generado por APIkit?","options":["Registra logs","Despliega la API","Sirve la consola de pruebas de la API","Gestiona errores de consola"],"correct":[2],"explanation":"Expone la consola en una ruta.","i18n":{"en":{"stem":"What does the APIkit-generated api-console flow do?","options":["Writes logs","Deploys the API","Serves the API test console","Handles console errors"],"explanation":"It exposes the console on a path."}}},{"domain":"D5","source":"bank","stem":"¿Qué recomienda MuleSoft sobre la consola de APIkit en producción?","options":["Valorar desactivarla o protegerla","No tiene relevancia","Dejarla siempre pública para que los clientes prueben","Usarla para administrar la API"],"correct":[0],"explanation":"Reducir superficie de exposición.","i18n":{"en":{"stem":"What does MuleSoft recommend about the APIkit console in production?","options":["Consider disabling or protecting it","It doesn't matter","Always leave it public for customers to test","Use it to administer the API"],"explanation":"Reduce exposure surface."}}},{"domain":"D6","source":"bank","stem":"¿Cómo se pasan valores a una consulta del conector Database de forma segura?","options":["Escribiéndolos en un comentario de la consulta","Con una variable de entorno del sistema operativo","Concatenando el valor directamente en la sentencia SQL","Con parámetros de entrada (input parameters)"],"correct":[3],"explanation":"Los parámetros evitan inyección SQL.","i18n":{"en":{"stem":"How are values passed safely to a Database connector query?","options":["Writing them in a query comment","With an OS environment variable","Concatenating the value directly into the SQL","With input parameters"],"explanation":"Parameters prevent SQL injection."}}},{"domain":"D6","source":"bank","stem":"¿Qué sintaxis usa el conector Database para un parámetro de entrada llamado id?","options":["?id al final de la consulta",":id en la consulta y el valor en inputParameters","${id} como propiedad de configuración","#[id] dentro del texto SQL concatenado"],"correct":[1],"explanation":"SELECT * FROM t WHERE id = :id.","i18n":{"en":{"stem":"Which syntax does the Database connector use for an input parameter named id?","options":["?id at the end of the query",":id in the query with the value in inputParameters","${id} as a config property","#[id] concatenated in the SQL text"],"explanation":"SELECT * FROM t WHERE id = :id."}}},{"domain":"D6","source":"bank","stem":"¿Qué devuelve la operación Select del conector Database?","options":["Un único objeto siempre","El número de filas afectadas","Un archivo CSV con las filas devueltas por la consulta en el directorio temporal","Una lista de registros (array de objetos)"],"correct":[3],"explanation":"Select devuelve un iterable de filas.","i18n":{"en":{"stem":"What does the Database Select operation return?","options":["Always a single object","The number of affected rows","A CSV file with the query rows in the temp directory","A list of records (array of objects)"],"explanation":"Select returns an iterable of rows."}}},{"domain":"D6","source":"bank","stem":"¿Qué devuelve una operación Insert del conector Database?","options":["Información de filas afectadas y claves generadas si se piden","Un error si no se usa Select antes","Siempre las filas insertadas completas con todos sus campos","Los registros insertados completos siempre"],"correct":[0],"explanation":"Devuelve affectedRows y generatedKeys.","i18n":{"en":{"stem":"What does a Database Insert operation return?","options":["Affected rows info and generated keys if requested","An error unless Select runs first","Always the full inserted rows with every field","Always the full inserted records"],"explanation":"It returns affectedRows and generatedKeys."}}},{"domain":"D6","source":"bank","stem":"¿Qué operación conviene para insertar miles de filas de una vez?","options":["Stored Procedure obligatoriamente","Bulk Insert","Select con un INSERT dentro","Insert dentro de un For Each fila a fila"],"correct":[1],"explanation":"Bulk reduce viajes a la base de datos.","i18n":{"en":{"stem":"Which operation suits inserting thousands of rows at once?","options":["Mandatorily Stored Procedure","Bulk Insert","Select with an INSERT inside","Insert inside a For Each row by row"],"explanation":"Bulk reduces database round trips."}}},{"domain":"D6","source":"bank","stem":"¿Qué origen del conector Database inicia un flujo cuando hay filas nuevas?","options":["Select programado con un HTTP Listener","On Table Row","Database Listener HTTP","Scheduler sin consulta"],"correct":[1],"explanation":"On Table Row sondea con watermark.","i18n":{"en":{"stem":"Which Database source starts a flow when new rows appear?","options":["A Select scheduled with an HTTP Listener","On Table Row","Database HTTP Listener","Scheduler with no query"],"explanation":"On Table Row polls with a watermark."}}},{"domain":"D6","source":"bank","stem":"¿Para qué sirve la columna de marca de agua (watermark) en On Table Row?","options":["Cifrar las filas leídas","Ordenar los resultados alfabéticamente","Borrar filas procesadas","Procesar solo filas nuevas desde la última ejecución"],"correct":[3],"explanation":"Evita reprocesar filas.","i18n":{"en":{"stem":"What is the watermark column for in On Table Row?","options":["Encrypting read rows","Sorting results alphabetically","Deleting processed rows","Processing only rows new since the last run"],"explanation":"It avoids reprocessing rows."}}},{"domain":"D6","source":"bank","stem":"¿Qué estrategia de conexión mantiene conexiones reutilizables a la base de datos?","options":["Abrir una conexión nueva en cada fila","Conectar solo al desplegar","Pooling de conexiones","Una sola conexión compartida por todas las apps"],"correct":[2],"explanation":"El pool mejora rendimiento.","i18n":{"en":{"stem":"Which connection strategy keeps reusable database connections?","options":["A new connection per row","Connecting only at deploy","Connection pooling","One connection shared by all apps"],"explanation":"Pooling improves performance."}}},{"domain":"D6","source":"bank","stem":"¿Qué operación del conector File lee el contenido de un archivo concreto?","options":["Copy","List","Write","Read"],"correct":[3],"explanation":"Read devuelve el contenido y FileAttributes.","i18n":{"en":{"stem":"Which File connector operation reads a specific file's content?","options":["Copy","List","Write","Read"],"explanation":"Read returns content and FileAttributes."}}},{"domain":"D6","source":"bank","stem":"¿Qué origen del conector File inicia un flujo cuando aparece un archivo nuevo?","options":["List sin directorio","Read programado en el listener","On New or Updated File","Write con modo append"],"correct":[2],"explanation":"Sondea un directorio.","i18n":{"en":{"stem":"Which File source starts a flow when a new file appears?","options":["List with no directory","A Read scheduled in the listener","On New or Updated File","Write in append mode"],"explanation":"It polls a directory."}}},{"domain":"D6","source":"bank","stem":"¿Qué conviene configurar en On New or Updated File para no procesar el mismo archivo dos veces?","options":["Desactivar el pooling","Mover o renombrar el archivo tras leerlo, o usar watermark","Leerlo dos veces para comprobarlo","Aumentar la frecuencia de sondeo"],"correct":[1],"explanation":"autoDelete, moveToDirectory o watermark.","i18n":{"en":{"stem":"What should be set in On New or Updated File to avoid processing a file twice?","options":["Disable pooling","Move or rename the file after reading, or use watermark","Read it twice to check","Increase polling frequency"],"explanation":"autoDelete, moveToDirectory or watermark."}}},{"domain":"D6","source":"bank","stem":"¿Qué modos de escritura ofrece la operación Write del conector File?","options":["READ y WRITE","INSERT y UPDATE","OVERWRITE, APPEND y CREATE_NEW","Solo OVERWRITE"],"correct":[2],"explanation":"mode controla el comportamiento.","i18n":{"en":{"stem":"Which write modes does the File Write operation offer?","options":["READ and WRITE","INSERT and UPDATE","OVERWRITE, APPEND and CREATE_NEW","Only OVERWRITE"],"explanation":"mode controls behavior."}}},{"domain":"D6","source":"bank","stem":"¿Qué conector se usa para leer archivos de un servidor remoto por SSH?","options":["HTTP","File local","SFTP","FTP sin cifrado"],"correct":[2],"explanation":"SFTP usa SSH.","i18n":{"en":{"stem":"Which connector reads files from a remote server over SSH?","options":["HTTP","Local File","SFTP","Unencrypted FTP"],"explanation":"SFTP uses SSH."}}},{"domain":"D6","source":"bank","stem":"¿Qué devuelve la operación List del conector File?","options":["El número de directorios","Una colección de archivos con sus atributos","El contenido concatenado de todos los archivos","Un único archivo"],"correct":[1],"explanation":"List devuelve mensajes por archivo.","i18n":{"en":{"stem":"What does the File List operation return?","options":["The number of directories","A collection of files with their attributes","All files' concatenated content","A single file"],"explanation":"List returns a message per file."}}},{"domain":"D6","source":"bank","stem":"¿Qué configuración del HTTP Request define host, puerto y protocolo comunes?","options":["La ruta del listener","El Logger","Un HTTP Request configuration global","El archivo pom.xml"],"correct":[2],"explanation":"El path se define en cada operación.","i18n":{"en":{"stem":"Which HTTP Request setting defines common host, port and protocol?","options":["The listener path","The Logger","A global HTTP Request configuration","pom.xml"],"explanation":"The path is set per operation."}}},{"domain":"D6","source":"bank","stem":"¿Cómo se envía un parámetro de consulta en un HTTP Request?","options":["En el cuerpo de la petición siempre","Concatenándolo al host del global config","En una variable con el nombre query","En la sección Query Parameters de la operación"],"correct":[3],"explanation":"queryParams se define en la operación.","i18n":{"en":{"stem":"How is a query parameter sent in an HTTP Request?","options":["Always in the request body","Concatenated to the global config host","In a variable named query","In the operation's Query Parameters section"],"explanation":"queryParams is set on the operation."}}},{"domain":"D6","source":"bank","stem":"¿Qué conector consume servicios web SOAP?","options":["Web Service Consumer","HTTP Listener","Database","File, leyendo el WSDL como archivo local"],"correct":[0],"explanation":"Usa el WSDL para operaciones.","i18n":{"en":{"stem":"Which connector consumes SOAP web services?","options":["Web Service Consumer","HTTP Listener","Database","File, reading the WSDL as a local file"],"explanation":"It uses the WSDL for operations."}}},{"domain":"D6","source":"bank","stem":"¿Qué necesita el Web Service Consumer para configurarse?","options":["Un Scheduler que llame periódicamente al endpoint SOAP","Una especificación RAML","Un conector de base de datos","La ubicación del WSDL, servicio y puerto"],"correct":[3],"explanation":"El WSDL define operaciones y mensajes.","i18n":{"en":{"stem":"What does the Web Service Consumer need to be configured?","options":["A Scheduler calling the SOAP endpoint periodically","A RAML spec","A database connector","The WSDL location, service and port"],"explanation":"The WSDL defines operations and messages."}}},{"domain":"D6","source":"bank","stem":"¿Qué formato espera normalmente el cuerpo de una operación SOAP en Mule 4?","options":["Texto plano","JSON libre","CSV","XML acorde al esquema del WSDL"],"correct":[3],"explanation":"Se construye con DataWeave a XML.","i18n":{"en":{"stem":"What format does a SOAP operation body usually expect in Mule 4?","options":["Plain text","Free JSON","CSV","XML matching the WSDL schema"],"explanation":"Built with DataWeave to XML."}}},{"domain":"D6","source":"bank","stem":"¿Qué conector permite crear y consultar registros de Salesforce desde Mule?","options":["Database con JDBC a Salesforce","File","HTTP Request a la web de Salesforce sin autenticación","Salesforce Connector"],"correct":[3],"explanation":"Ofrece operaciones como Query, Create, Upsert.","i18n":{"en":{"stem":"Which connector creates and queries Salesforce records from Mule?","options":["Database via JDBC to Salesforce","File","HTTP Request to Salesforce site unauthenticated","Salesforce Connector"],"explanation":"It offers Query, Create, Upsert, etc."}}},{"domain":"D6","source":"bank","stem":"¿Qué lenguaje se usa en la operación Query del Salesforce Connector?","options":["SOQL","DataWeave","GraphQL","SQL ANSI completo"],"correct":[0],"explanation":"Salesforce Object Query Language.","i18n":{"en":{"stem":"Which language is used in the Salesforce Connector Query operation?","options":["SOQL","DataWeave","GraphQL","Full ANSI SQL"],"explanation":"Salesforce Object Query Language."}}},{"domain":"D6","source":"bank","stem":"¿Qué estrategia permite a un conector reintentar la conexión si el sistema remoto cae?","options":["Un Transform Message","Un Logger con nivel ERROR","Estrategia de reconexión","Un ámbito Async"],"correct":[2],"explanation":"reconnection con frecuencia e intentos.","i18n":{"en":{"stem":"Which strategy lets a connector retry connecting if the remote system goes down?","options":["A Transform Message","A Logger at ERROR","Reconnection strategy","An Async scope"],"explanation":"reconnection with frequency and attempts."}}},{"domain":"D6","source":"bank","stem":"¿Qué dos conectores sirven para mensajería entre sistemas? (Elige 2)","options":["JMS","Logger","Anypoint MQ","File Read","Database Select"],"correct":[0,2],"explanation":"Colas y temas.","i18n":{"en":{"stem":"Which two connectors serve messaging between systems? (Choose 2)","options":["JMS","Logger","Anypoint MQ","File Read","Database Select"],"explanation":"Queues and topics."}}},{"domain":"D6","source":"bank","stem":"¿Qué conector usar para comunicación por colas dentro de la misma aplicación Mule?","options":["File","HTTP","VM","JMS externo"],"correct":[2],"explanation":"VM es intraaplicación (o dominio).","i18n":{"en":{"stem":"Which connector for queue communication within the same Mule app?","options":["File","HTTP","VM","External JMS"],"explanation":"VM is intra-app (or domain)."}}},{"domain":"D6","source":"bank","stem":"¿Qué indica el error DB:CONNECTIVITY?","options":["El SQL tiene un error de sintaxis","Que la consulta devolvió un payload JSON en lugar de filas","La consulta devolvió cero filas","No se pudo conectar con la base de datos"],"correct":[3],"explanation":"Error de conexión.","i18n":{"en":{"stem":"What does DB:CONNECTIVITY indicate?","options":["The SQL has a syntax error","The query returned a JSON payload instead of rows","The query returned zero rows","The database couldn't be reached"],"explanation":"A connection error."}}},{"domain":"D6","source":"bank","stem":"¿Qué indica el error HTTP:NOT_FOUND en un HTTP Request?","options":["La red está caída","Falta la configuración global","El servicio remoto devolvió 404","El listener no encontró el flujo"],"correct":[2],"explanation":"Los códigos de error remotos se mapean a tipos HTTP.","i18n":{"en":{"stem":"What does HTTP:NOT_FOUND on an HTTP Request indicate?","options":["The network is down","The global config is missing","The remote service returned 404","The listener didn't find the flow"],"explanation":"Remote error codes map to HTTP types."}}},{"domain":"D6","source":"bank","stem":"¿Cómo se evita que un HTTP Request lance error ante códigos 4xx concretos?","options":["Usando un Logger","Cambiando el puerto","Configurando el validador de respuesta con los códigos aceptados","Desactivando el conector"],"correct":[2],"explanation":"responseValidator con successStatusCodes.","i18n":{"en":{"stem":"How is an HTTP Request kept from failing on specific 4xx codes?","options":["Use a Logger","Change the port","Configure the response validator with accepted codes","Disable the connector"],"explanation":"responseValidator with successStatusCodes."}}},{"domain":"D6","source":"bank","stem":"¿Qué dos operaciones ofrece el conector Database además de Select e Insert? (Elige 2)","options":["Listen HTTP","Publish","Read file","Update","Stored Procedure"],"correct":[3,4],"explanation":"También Delete, Bulk y DDL.","i18n":{"en":{"stem":"Which two operations does the Database connector offer besides Select and Insert? (Choose 2)","options":["Listen HTTP","Publish","Read file","Update","Stored Procedure"],"explanation":"Also Delete, Bulk and DDL."}}},{"domain":"D6","source":"bank","stem":"¿Qué se necesita en el proyecto para conectar a una base de datos MySQL?","options":["Un subflujo con la cadena de conexión escrita en un Set Variable","El driver JDBC como dependencia","Una política de API Manager","Un archivo RAML"],"correct":[1],"explanation":"El driver se añade al pom.","i18n":{"en":{"stem":"What's needed in the project to connect to MySQL?","options":["A subflow with the connection string in a Set Variable","The JDBC driver as a dependency","An API Manager policy","A RAML file"],"explanation":"The driver is added to the pom."}}},{"domain":"D6","source":"bank","stem":"¿Qué devuelve el Salesforce Connector en una operación Create?","options":["Nada: la operación Create no devuelve información al flujo","El objeto completo de Salesforce siempre","Un CSV","Resultados por registro con id y éxito o errores"],"correct":[3],"explanation":"SaveResult por registro.","i18n":{"en":{"stem":"What does the Salesforce Connector return on Create?","options":["Nothing: Create returns no information to the flow","Always the full Salesforce object","A CSV","Per-record results with id and success or errors"],"explanation":"A SaveResult per record."}}},{"domain":"D6","source":"bank","stem":"¿Qué origen del Salesforce Connector escucha cambios en registros?","options":["HTTP Listener con ruta /salesforce","File On New File apuntando al directorio de exportaciones de Salesforce","On New Object / On Modified Object o Replay Channel","Query programada con un Logger"],"correct":[2],"explanation":"Sources de eventos y streaming.","i18n":{"en":{"stem":"Which Salesforce Connector source listens for record changes?","options":["HTTP Listener on /salesforce","File On New File pointed at the Salesforce export directory","On New Object / On Modified Object or Replay Channel","A Query scheduled with a Logger"],"explanation":"Event and streaming sources."}}},{"domain":"D6","source":"bank","stem":"¿Qué conviene para conectar a un sistema sin conector disponible pero con API REST?","options":["Un conector Database","Un Logger que registre las peticiones para que otro equipo las envíe","Copiar archivos a mano","HTTP Request o REST Connect desde la especificación"],"correct":[3],"explanation":"HTTP Request o un conector generado.","i18n":{"en":{"stem":"What's advisable for a system with no connector but a REST API?","options":["A Database connector","A Logger recording requests for another team to send","Copying files by hand","HTTP Request or REST Connect from the spec"],"explanation":"HTTP Request or a generated connector."}}},{"domain":"D6","source":"bank","stem":"¿Qué hace la operación Write del conector File si el directorio no existe y createParentDirectories es true?","options":["Crea los directorios necesarios","Ignora la escritura y devuelve el payload sin cambios ni error","Lanza siempre un error","Escribe en el directorio raíz"],"correct":[0],"explanation":"Por defecto crea directorios padre.","i18n":{"en":{"stem":"What does File Write do if the directory doesn't exist and createParentDirectories is true?","options":["Creates the needed directories","It skips the write and returns the payload unchanged with no error","Always throws","Writes to the root"],"explanation":"It creates parent directories by default."}}},{"domain":"D6","source":"bank","stem":"¿Qué dos atributos del archivo están disponibles tras On New or Updated File? (Elige 2)","options":["fileName","queryParams","method","lastModifiedTime","statusCode"],"correct":[0,3],"explanation":"FileAttributes.","i18n":{"en":{"stem":"Which two file attributes are available after On New or Updated File? (Choose 2)","options":["fileName","queryParams","method","lastModifiedTime","statusCode"],"explanation":"FileAttributes."}}},{"domain":"D6","source":"bank","stem":"¿Qué conviene si un conector de base de datos tarda en responder y bloquea hilos?","options":["Aumentar los logs a DEBUG","Configurar timeouts y revisar el pool","Usar Flow Reference para llamar al conector desde otro flujo","Eliminar el manejo de errores"],"correct":[1],"explanation":"Timeouts y dimensionamiento del pool.","i18n":{"en":{"stem":"What if a database connector is slow and blocks threads?","options":["Raise logs to DEBUG","Set timeouts and review the pool","Use Flow Reference to call the connector from another flow","Remove error handling"],"explanation":"Timeouts and pool sizing."}}},{"domain":"D6","source":"bank","stem":"¿Qué indica el parámetro fetchSize en una consulta Select?","options":["El tiempo de espera","Cuántas filas se traen por bloque al hacer streaming","El tamaño del pool","El número máximo de columnas"],"correct":[1],"explanation":"Ayuda al streaming de grandes resultados.","i18n":{"en":{"stem":"What does fetchSize indicate on a Select?","options":["Timeout","How many rows are fetched per chunk when streaming","Pool size","Max columns"],"explanation":"It helps stream large results."}}},{"domain":"D6","source":"bank","stem":"¿Qué conector publica y consume mensajes en Anypoint MQ?","options":["Database connector","VM connector","Web Service Consumer","Anypoint MQ connector"],"correct":[3],"explanation":"Publish, Consume y Subscriber.","i18n":{"en":{"stem":"Which connector publishes and consumes Anypoint MQ messages?","options":["Database connector","VM connector","Web Service Consumer","Anypoint MQ connector"],"explanation":"Publish, Consume and Subscriber."}}},{"domain":"D6","source":"bank","stem":"¿Qué ventaja tiene usar colas entre aplicaciones?","options":["Eliminar la necesidad de errores","Que el consumidor responde de forma síncrona","Desacoplar productor y consumidor","Compartir variables"],"correct":[2],"explanation":"Resiliencia y desacoplamiento.","i18n":{"en":{"stem":"What's the advantage of queues between apps?","options":["No errors needed","The consumer replies synchronously","Decoupling producer and consumer","Sharing variables"],"explanation":"Resilience and decoupling."}}},{"domain":"D6","source":"bank","stem":"¿Qué tipo de autenticación admite el HTTP Request?","options":["Solo API keys en la URL","Solo sin autenticación","Basic, Digest, NTLM y OAuth, entre otras","Solo certificados"],"correct":[2],"explanation":"Varias opciones de autenticación.","i18n":{"en":{"stem":"Which authentication does HTTP Request support?","options":["Only API keys in the URL","Only none","Basic, Digest, NTLM and OAuth, among others","Only certificates"],"explanation":"Several auth options."}}},{"domain":"D6","source":"bank","stem":"¿Qué indica el error FILE:ILLEGAL_PATH?","options":["Falta un permiso de red","La ruta indicada no es válida o no existe","El archivo está vacío","El archivo es muy grande"],"correct":[1],"explanation":"Ruta inválida.","i18n":{"en":{"stem":"What does FILE:ILLEGAL_PATH indicate?","options":["A network permission is missing","The given path is invalid or missing","The file is empty","The file is too big"],"explanation":"Invalid path."}}},{"domain":"D6","source":"bank","stem":"¿Qué recomienda MuleSoft para credenciales de conectores?","options":["Pasarlas en variables desde el cliente","Publicarlas en Exchange para que los equipos las reutilicen","Propiedades seguras o gestor de secretos","Escribirlas en el XML"],"correct":[2],"explanation":"Nunca en texto plano.","i18n":{"en":{"stem":"What does MuleSoft recommend for connector credentials?","options":["Passing them in variables from the client","Publish them to Exchange so teams can reuse them","Secure properties or a secrets manager","Writing them in the XML"],"explanation":"Never in plain text."}}},{"domain":"D6","source":"bank","stem":"¿Qué devuelve la operación Update del conector Database?","options":["Un booleano siempre","Las filas actualizadas completas","El SQL ejecutado","El número de filas afectadas"],"correct":[3],"explanation":"affectedRows.","i18n":{"en":{"stem":"What does the Database Update operation return?","options":["Always a boolean","The full updated rows","The executed SQL","The number of affected rows"],"explanation":"affectedRows."}}},{"domain":"D6","source":"bank","stem":"¿Qué dos opciones permiten llamar a un procedimiento almacenado con parámetros de salida? (Elige 2)","options":["File Write","Definir outputParameters","Operación Stored Procedure","VM Publish","Select con CALL dentro concatenado"],"correct":[1,2],"explanation":"Stored Procedure con in/out params.","i18n":{"en":{"stem":"Which two options call a stored procedure with output parameters? (Choose 2)","options":["File Write","Defining outputParameters","Stored Procedure operation","VM Publish","Select with a concatenated CALL"],"explanation":"Stored Procedure with in/out params."}}},{"domain":"D6","source":"bank","stem":"¿Qué indica la opción de conector \"Test Connection\" en Studio?","options":["Ejecuta la consulta en producción","Verifica que la configuración puede conectarse","Genera datos de prueba","Despliega la app"],"correct":[1],"explanation":"Validación de configuración.","i18n":{"en":{"stem":"What does a connector's Test Connection in Studio do?","options":["Runs the query in production","Verifies the config can connect","Generates test data","Deploys the app"],"explanation":"Config validation."}}},{"domain":"D6","source":"bank","stem":"¿Qué conviene para leer un archivo muy grande sin cargarlo entero en memoria?","options":["Convertirlo a String primero","Duplicarlo y leer cada copia en un flujo distinto en paralelo","Leerlo entero en una variable","Usar streaming y procesarlo por partes"],"correct":[3],"explanation":"Streaming y procesamiento por bloques.","i18n":{"en":{"stem":"What's advisable to read a huge file without loading it all into memory?","options":["Convert it to String first","Duplicate it and read each copy in a different flow in parallel","Read it all into a variable","Use streaming and process in parts"],"explanation":"Streaming and chunked processing."}}},{"domain":"D6","source":"bank","stem":"Un flujo debe llamar a un servicio REST externo que exige un token en la cabecera Authorization. ¿Dónde se añade?","options":["En el archivo pom.xml como propiedad de Maven del proyecto","En el HTTP Listener del flujo que recibe la petición del cliente","En el path del HTTP Request como parámetro adicional al final de la URL","En la sección Headers del HTTP Request"],"correct":[3],"explanation":"Las cabeceras se definen en la operación de request.","i18n":{"en":{"stem":"A flow must call an external REST service needing a token in the Authorization header. Where is it added?","options":["In pom.xml as a project Maven property","In the flow's HTTP Listener that receives the client request","In the HTTP Request path as an extra parameter at the end of the URL","In the HTTP Request Headers section"],"explanation":"Headers are set on the request operation."}}},{"domain":"D6","source":"bank","stem":"¿Qué conector conviene para recoger cada noche un archivo CSV de un proveedor en un servidor FTP sin cifrar?","options":["Web Service Consumer apuntando al servidor de archivos","Database con un driver de ficheros planos","SFTP, aunque el servidor del proveedor no ofrezca SSH","FTP"],"correct":[3],"explanation":"Se usa el conector que coincide con el protocolo del servidor.","i18n":{"en":{"stem":"Which connector suits collecting a supplier's nightly CSV from an unencrypted FTP server?","options":["Web Service Consumer pointed at the file server","Database with a flat-file driver","SFTP, even though the supplier's server offers no SSH","FTP"],"explanation":"Use the connector matching the server protocol."}}},{"domain":"D6","source":"bank","stem":"¿Qué dos riesgos evita usar parámetros de entrada en el conector Database? (Elige 2)","options":["Inyección SQL","Errores de formato al concatenar valores","Que el driver JDBC no se cargue al arrancar la aplicación","Que la consulta devuelva demasiadas columnas en el resultado","Que el pool de conexiones se quede sin hilos disponibles"],"correct":[0,1],"explanation":"Los parámetros escapan y tipan los valores.","i18n":{"en":{"stem":"Which two risks does using input parameters in the Database connector avoid? (Choose 2)","options":["SQL injection","Format errors from concatenating values","The JDBC driver not loading at startup","The query returning too many result columns","The connection pool running out of threads"],"explanation":"Parameters escape and type values."}}},{"domain":"D6","source":"bank","stem":"Un HTTP Request a un servicio lento supera el tiempo de espera. ¿Qué ajuste se revisa?","options":["El nivel del Logger configurado en log4j2.xml","El responseTimeout de la operación","El tipo MIME de la respuesta esperada","El número de workers de la aplicación en Runtime Manager"],"correct":[1],"explanation":"El timeout se configura en la petición o la configuración.","i18n":{"en":{"stem":"An HTTP Request to a slow service times out. Which setting is reviewed?","options":["The Logger level in log4j2.xml","The operation's responseTimeout","The expected response MIME type","The number of app workers in Runtime Manager"],"explanation":"Timeout is set on the request or config."}}},{"domain":"D6","source":"bank","stem":"¿Qué devuelve la operación Consume de Anypoint MQ?","options":["Un error si la cola tiene más de un mensaje pendiente","El número de mensajes pendientes sin leer su contenido","Todos los mensajes de la cola de una vez y los borra al instante","Un mensaje de la cola, que luego se confirma (ACK)"],"correct":[3],"explanation":"Se confirma con ACK o se rechaza con NACK.","i18n":{"en":{"stem":"What does the Anypoint MQ Consume operation return?","options":["An error if more than one message is pending","The pending message count without reading content","All queue messages at once, deleting them immediately","A message from the queue, later acknowledged (ACK)"],"explanation":"It's confirmed with ACK or rejected with NACK."}}},{"domain":"D7","source":"bank","stem":"¿Qué hace el ámbito For Each?","options":["Itera una colección y procesa cada elemento secuencialmente","Procesa todos los elementos en paralelo y agrega los resultados","Divide los registros en lotes persistentes con pasos y resumen final","Repite el flujo hasta que no haya errores"],"correct":[0],"explanation":"For Each es secuencial y síncrono.","i18n":{"en":{"stem":"What does the For Each scope do?","options":["Iterates a collection and processes each element sequentially","Processes all elements in parallel and aggregates results","Splits records into persistent batches with steps and a final summary","Repeats the flow until there are no errors"],"explanation":"For Each is sequential and synchronous."}}},{"domain":"D7","source":"bank","stem":"¿Cuál es el payload después de un For Each?","options":["Un array con los payloads producidos en cada iteración del bucle","Un array con los resultados de cada iteración","El payload original que había antes del For Each","El resultado de la última iteración"],"correct":[2],"explanation":"For Each no modifica el payload exterior.","i18n":{"en":{"stem":"What is the payload after a For Each?","options":["An array of the payloads produced in each loop iteration","An array of each iteration's results","The original payload from before the For Each","The last iteration's result"],"explanation":"For Each doesn't modify the outer payload."}}},{"domain":"D7","source":"bank","stem":"¿Qué variable contiene el número de iteración dentro de un For Each?","options":["vars.counter","attributes.iteration","vars.index, que empieza en cero","payload.counter"],"correct":[0],"explanation":"counter empieza en 1 por defecto.","i18n":{"en":{"stem":"Which variable holds the iteration number inside a For Each?","options":["vars.counter","attributes.iteration","vars.index, which starts at zero","payload.counter"],"explanation":"counter starts at 1 by default."}}},{"domain":"D7","source":"bank","stem":"¿Qué variable da acceso al mensaje completo original dentro de un For Each?","options":["payload.parent","attributes.root","vars.rootMessage","vars.originalPayload"],"correct":[2],"explanation":"rootMessage contiene el mensaje anterior al For Each.","i18n":{"en":{"stem":"Which variable gives access to the original full message inside a For Each?","options":["payload.parent","attributes.root","vars.rootMessage","vars.originalPayload"],"explanation":"rootMessage holds the pre-For Each message."}}},{"domain":"D7","source":"bank","stem":"¿Qué ocurre con las variables modificadas dentro de un For Each?","options":["Solo persisten si son de tipo String","Se convierten en atributos del evento al salir del ámbito","Se descartan al terminar cada iteración","Los cambios persisten después del ámbito"],"correct":[3],"explanation":"A diferencia del payload, las variables se mantienen.","i18n":{"en":{"stem":"What happens to variables modified inside a For Each?","options":["They persist only if String","They become event attributes when leaving the scope","They're discarded after each iteration","Changes persist after the scope"],"explanation":"Unlike the payload, variables persist."}}},{"domain":"D7","source":"bank","stem":"¿Qué permite el parámetro batchSize de For Each?","options":["Procesar en paralelo varios elementos","Limitar el número total de elementos","Agrupar varios elementos por iteración","Persistir los elementos en disco"],"correct":[2],"explanation":"Cada iteración recibe un subarray.","i18n":{"en":{"stem":"What does For Each's batchSize allow?","options":["Processing several elements in parallel","Limiting the total element count","Grouping several elements per iteration","Persisting elements to disk"],"explanation":"Each iteration gets a sub-array."}}},{"domain":"D7","source":"bank","stem":"¿Qué ocurre por defecto si falla una iteración de For Each?","options":["Se reintenta indefinidamente","El error se propaga y se detiene el For Each","Se ignora sin registrar","Se salta el elemento y continúa con el siguiente"],"correct":[1],"explanation":"Se puede envolver en Try para continuar.","i18n":{"en":{"stem":"What happens by default if a For Each iteration fails?","options":["It retries indefinitely","The error propagates and For Each stops","It's ignored unlogged","The element is skipped and the next continues"],"explanation":"Wrap in Try to continue."}}},{"domain":"D7","source":"bank","stem":"¿Qué ámbito procesa elementos de una colección en paralelo y devuelve los resultados?","options":["For Each con batchSize mayor que 1","Parallel For Each","Async dentro de un For Each","Cache"],"correct":[1],"explanation":"Parallel For Each agrega resultados en orden.","i18n":{"en":{"stem":"Which scope processes collection elements in parallel and returns results?","options":["For Each with batchSize over 1","Parallel For Each","Async inside a For Each","Cache"],"explanation":"Parallel For Each aggregates results in order."}}},{"domain":"D7","source":"bank","stem":"¿Qué payload deja Parallel For Each al terminar?","options":["El payload original que había antes de entrar en el ámbito","El payload original","Solo el último resultado","Una colección con el resultado de cada ruta"],"correct":[3],"explanation":"A diferencia de For Each.","i18n":{"en":{"stem":"What payload does Parallel For Each leave when done?","options":["The original payload from before entering the scope","The original payload","Only the last result","A collection with each route's result"],"explanation":"Unlike For Each."}}},{"domain":"D7","source":"bank","stem":"¿Para qué está pensado un Batch Job?","options":["Atender peticiones HTTP síncronas de baja latencia","Procesar grandes volúmenes de registros de forma fiable y asíncrona","Enrutar mensajes por contenido hacia distintos sistemas en tiempo real","Transformar un único registro en tiempo real"],"correct":[1],"explanation":"Batch persiste registros y procesa en bloques.","i18n":{"en":{"stem":"What is a Batch Job designed for?","options":["Serving low-latency synchronous HTTP requests","Processing large record volumes reliably and asynchronously","Routing messages by content to different systems in real time","Transforming a single record in real time"],"explanation":"Batch persists records and processes in blocks."}}},{"domain":"D7","source":"bank","stem":"¿Qué tres fases tiene un Batch Job?","options":["Inicio, pausa y reanudación, controladas desde Runtime Manager","Validación, despliegue y monitorización","Carga y envío, procesamiento y finalización (On Complete)","Lectura, escritura y borrado"],"correct":[2],"explanation":"Load and dispatch, process, on complete.","i18n":{"en":{"stem":"Which three phases does a Batch Job have?","options":["Start, pause and resume, controlled from Runtime Manager","Validate, deploy and monitor","Load and dispatch, process, and On Complete","Read, write and delete"],"explanation":"Load and dispatch, process, on complete."}}},{"domain":"D7","source":"bank","stem":"¿Qué recibe la fase On Complete de un Batch Job como payload?","options":["El payload original de la entrada","El último registro","La lista completa de registros procesados","Un resumen con registros procesados, exitosos y fallidos"],"correct":[3],"explanation":"BatchJobResult con estadísticas.","i18n":{"en":{"stem":"What does a Batch Job's On Complete phase receive as payload?","options":["The original input payload","The last record","The full list of processed records","A summary of processed, successful and failed records"],"explanation":"BatchJobResult with statistics."}}},{"domain":"D7","source":"bank","stem":"¿Qué es un Batch Step?","options":["Una etapa por la que pasa cada registro","Un archivo de configuración del lote","Un tipo de origen de flujo","Un hilo del pool de procesamiento asignado a un registro concreto"],"correct":[0],"explanation":"Los registros pasan por los steps en orden.","i18n":{"en":{"stem":"What is a Batch Step?","options":["A stage each record passes through","A batch config file","A flow source type","A processing pool thread assigned to a specific record"],"explanation":"Records pass through steps in order."}}},{"domain":"D7","source":"bank","stem":"¿Qué controla la política de aceptación (accept policy) de un Batch Step?","options":["El número de hilos del lote","El tamaño de bloque","Qué registros entran según su estado: no fallidos, solo fallidos o todos","El formato de salida"],"correct":[2],"explanation":"NO_FAILURES por defecto; ONLY_FAILURES; ALL.","i18n":{"en":{"stem":"What does a Batch Step's accept policy control?","options":["Batch thread count","Block size","Which records enter by status: no failures, only failures or all","Output format"],"explanation":"NO_FAILURES by default; ONLY_FAILURES; ALL."}}},{"domain":"D7","source":"bank","stem":"¿Qué permite la expresión de aceptación (accept expression) de un Batch Step?","options":["Filtrar registros por una condición","Reintentar registros fallidos","Cambiar el tamaño de bloque del lote según el contenido del registro","Cambiar el orden de los pasos"],"correct":[0],"explanation":"Solo procesa registros que cumplen la expresión.","i18n":{"en":{"stem":"What does a Batch Step accept expression allow?","options":["Filtering records by a condition","Retrying failed records","Changing the job's block size based on record content","Reordering steps"],"explanation":"Only matching records are processed."}}},{"domain":"D7","source":"bank","stem":"¿Qué hace el Batch Aggregator dentro de un Batch Step?","options":["Combina varios Batch Jobs en uno","Agrupa registros para procesarlos juntos, por ejemplo un bulk insert","Divide un registro en varios","Calcula estadísticas finales"],"correct":[1],"explanation":"Aggregator con tamaño fijo o streaming.","i18n":{"en":{"stem":"What does the Batch Aggregator do inside a Batch Step?","options":["Combines several Batch Jobs","Groups records to process together, e.g. a bulk insert","Splits one record into many","Computes final statistics"],"explanation":"Aggregator with fixed size or streaming."}}},{"domain":"D7","source":"bank","stem":"¿Qué tamaño de bloque (block size) usa un Batch Job por defecto?","options":["1.000 registros","1 registro","Todo el conjunto","100 registros"],"correct":[3],"explanation":"Los registros se procesan en bloques de 100.","i18n":{"en":{"stem":"What block size does a Batch Job use by default?","options":["1,000 records","1 record","The whole set","100 records"],"explanation":"Records are processed in blocks of 100."}}},{"domain":"D7","source":"bank","stem":"¿Qué controla maxFailedRecords en un Batch Job?","options":["El número de reintentos por registro","Cuántos registros pueden fallar antes de detener el lote","El tamaño de bloque","El número de steps que puede tener el lote como máximo"],"correct":[1],"explanation":"0 detiene al primer fallo; -1 nunca.","i18n":{"en":{"stem":"What does maxFailedRecords control in a Batch Job?","options":["Retries per record","How many records may fail before stopping the job","Block size","The maximum number of steps the job may have"],"explanation":"0 stops on first failure; -1 never."}}},{"domain":"D7","source":"bank","stem":"¿Qué valor de maxFailedRecords permite que el lote continúe con cualquier número de fallos?","options":["100","-1","0","1"],"correct":[1],"explanation":"-1 = sin límite.","i18n":{"en":{"stem":"Which maxFailedRecords value lets the job continue with any number of failures?","options":["100","-1","0","1"],"explanation":"-1 = unlimited."}}},{"domain":"D7","source":"bank","stem":"¿Qué ocurre con un registro que falla en un Batch Step?","options":["Se reintenta indefinidamente","Se marca como fallido y no pasa a los steps que solo aceptan no fallidos","Detiene siempre todo el lote inmediatamente","Se elimina del lote sin registrar el fallo en el resultado final"],"correct":[1],"explanation":"Según maxFailedRecords y accept policy.","i18n":{"en":{"stem":"What happens to a record that fails in a Batch Step?","options":["It retries indefinitely","It's marked failed and skips steps that only accept non-failed","It always stops the whole job immediately","It's dropped from the job without logging the failure in the result"],"explanation":"Per maxFailedRecords and accept policy."}}},{"domain":"D7","source":"bank","stem":"¿Qué son las variables de registro en un Batch Job?","options":["Variables globales compartidas por todos los registros","Propiedades de configuración","Variables ligadas a cada registro que persisten entre steps","Atributos HTTP"],"correct":[2],"explanation":"Cada registro conserva sus variables entre steps.","i18n":{"en":{"stem":"What are record variables in a Batch Job?","options":["Global variables shared by all records","Config properties","Variables tied to each record persisting across steps","HTTP attributes"],"explanation":"Each record keeps its variables across steps."}}},{"domain":"D7","source":"bank","stem":"¿Es síncrono el Batch Job respecto al flujo que lo invoca?","options":["Solo si el lote tiene un step","Depende del tamaño de bloque: con bloques pequeños es síncrono","Sí, espera a que termine el último registro","No: el flujo continúa sin esperar el resultado del lote"],"correct":[3],"explanation":"Batch es asíncrono.","i18n":{"en":{"stem":"Is the Batch Job synchronous relative to the invoking flow?","options":["Only with one step","Depends on block size: small blocks make it synchronous","Yes, it waits for the last record","No: the flow continues without waiting for the job"],"explanation":"Batch is asynchronous."}}},{"domain":"D7","source":"bank","stem":"¿Dónde persisten los registros durante un Batch Job?","options":["En la memoria del flujo invocante","En colas persistentes gestionadas por Mule","En el archivo pom.xml","En Exchange"],"correct":[1],"explanation":"Permite recuperación ante reinicios.","i18n":{"en":{"stem":"Where do records persist during a Batch Job?","options":["In the invoking flow's memory","In persistent queues managed by Mule","In pom.xml","In Exchange"],"explanation":"It allows recovery on restart."}}},{"domain":"D7","source":"bank","stem":"¿Qué dos casos de uso encajan con Batch? (Elige 2)","options":["Sincronizar cientos de miles de registros cada noche","Responder a una petición HTTP en milisegundos","Validar un único formulario web","Enrutar un mensaje por su tipo","Migrar datos entre sistemas"],"correct":[0,4],"explanation":"Volumen y fiabilidad.","i18n":{"en":{"stem":"Which two use cases fit Batch? (Choose 2)","options":["Syncing hundreds of thousands of records nightly","Answering an HTTP request in milliseconds","Validating one web form","Routing a message by type","Migrating data between systems"],"explanation":"Volume and reliability."}}},{"domain":"D7","source":"bank","stem":"¿Qué diferencia principal hay entre For Each y Batch Job?","options":["For Each solo funciona con XML","Batch no admite errores","For Each es síncrono y en memoria; Batch es asíncrono y persistente","For Each es asíncrono y Batch síncrono"],"correct":[2],"explanation":"Elegir según volumen y fiabilidad.","i18n":{"en":{"stem":"What's the main difference between For Each and Batch Job?","options":["For Each only works with XML","Batch doesn't support errors","For Each is sync and in-memory; Batch is async and persistent","For Each is async and Batch sync"],"explanation":"Choose by volume and reliability."}}},{"domain":"D7","source":"bank","stem":"¿Qué origen del conector Database facilita procesar solo filas nuevas automáticamente?","options":["Stored Procedure","On Table Row con watermark","Bulk Insert","Select dentro de un For Each"],"correct":[1],"explanation":"Watermark automático.","i18n":{"en":{"stem":"Which Database source eases processing only new rows automatically?","options":["Stored Procedure","On Table Row with watermark","Bulk Insert","Select inside a For Each"],"explanation":"Automatic watermark."}}},{"domain":"D7","source":"bank","stem":"¿Qué se usa para guardar manualmente el último valor procesado entre ejecuciones?","options":["attributes","Object Store","Una variable de flujo","Un Logger"],"correct":[1],"explanation":"Object Store persiste entre ejecuciones.","i18n":{"en":{"stem":"What's used to manually store the last processed value between runs?","options":["attributes","Object Store","A flow variable","A Logger"],"explanation":"Object Store persists between runs."}}},{"domain":"D7","source":"bank","stem":"¿Qué operaciones ofrece el conector Object Store?","options":["Select, Insert y Update","Read y Write de archivos","Store, Retrieve, Remove y Contains, entre otras","Publish y Consume"],"correct":[2],"explanation":"Almacén clave-valor.","i18n":{"en":{"stem":"Which operations does the Object Store connector offer?","options":["Select, Insert and Update","File Read and Write","Store, Retrieve, Remove and Contains, among others","Publish and Consume"],"explanation":"A key-value store."}}},{"domain":"D7","source":"bank","stem":"¿Qué indica que un Object Store sea persistente?","options":["Que solo admite valores de tipo String y se borra al reiniciar","Que se replica en Exchange","Sus valores sobreviven a reinicios de la aplicación","Que se borra al terminar el flujo"],"correct":[2],"explanation":"persistent=true.","i18n":{"en":{"stem":"What does a persistent Object Store mean?","options":["It only accepts String values and clears on restart","It's replicated in Exchange","Its values survive app restarts","It's cleared when the flow ends"],"explanation":"persistent=true."}}},{"domain":"D7","source":"bank","stem":"¿Qué hace la operación Retrieve de Object Store si la clave no existe y hay valor por defecto?","options":["Crea la clave vacía","Lanza siempre un error","Devuelve todas las claves","Devuelve el valor por defecto"],"correct":[3],"explanation":"defaultValue evita OS:KEY_NOT_FOUND.","i18n":{"en":{"stem":"What does Object Store Retrieve do if the key is missing but a default exists?","options":["Creates the key empty","Always throws","Returns all keys","Returns the default"],"explanation":"defaultValue avoids OS:KEY_NOT_FOUND."}}},{"domain":"D7","source":"bank","stem":"¿Qué error lanza Retrieve si la clave no existe y no hay valor por defecto?","options":["OS:STORE_NOT_AVAILABLE","MULE:EXPRESSION","OS:KEY_NOT_FOUND","DB:QUERY_EXECUTION"],"correct":[2],"explanation":"Error tipado del Object Store.","i18n":{"en":{"stem":"Which error does Retrieve throw if the key is missing with no default?","options":["OS:STORE_NOT_AVAILABLE","MULE:EXPRESSION","OS:KEY_NOT_FOUND","DB:QUERY_EXECUTION"],"explanation":"Typed Object Store error."}}},{"domain":"D7","source":"bank","stem":"¿Qué patrón aplica el watermark manual con Object Store?","options":["Procesar toda la tabla en cada ejecución","Leer el último valor, consultar desde ahí y guardar el nuevo valor","Borrar todas las filas procesadas de la tabla origen","Guardar el payload completo en el Object Store"],"correct":[1],"explanation":"Evita reprocesar datos.","i18n":{"en":{"stem":"Which pattern does manual watermarking with Object Store follow?","options":["Process the whole table each run","Read last value, query from there and store the new value","Delete all processed rows from the source table","Store the full payload in the Object Store"],"explanation":"It avoids reprocessing."}}},{"domain":"D7","source":"bank","stem":"¿Qué dos ámbitos procesan colecciones? (Elige 2)","options":["Choice","For Each","Try","Parallel For Each","Cache"],"correct":[1,3],"explanation":"Iteración secuencial y paralela.","i18n":{"en":{"stem":"Which two scopes process collections? (Choose 2)","options":["Choice","For Each","Try","Parallel For Each","Cache"],"explanation":"Sequential and parallel iteration."}}},{"domain":"D7","source":"bank","stem":"¿Qué conviene hacer en un Batch Step que inserta en base de datos para mejorar rendimiento?","options":["Insertar cada registro con un For Each dentro del step","Usar Flow Reference a un subflujo con Select","Usar un Batch Aggregator con Bulk Insert","Desactivar el pooling"],"correct":[2],"explanation":"Agregar e insertar en bloque.","i18n":{"en":{"stem":"What improves performance in a Batch Step inserting into a database?","options":["Insert each record with a For Each in the step","Flow Reference to a Select subflow","Use a Batch Aggregator with Bulk Insert","Disable pooling"],"explanation":"Aggregate and bulk insert."}}},{"domain":"D7","source":"bank","stem":"¿Qué indica el parámetro maxConcurrency de un Batch Job?","options":["El tamaño del bloque","Cuántos steps puede tener el lote y en qué orden se ejecutan","Cuántos bloques se procesan en paralelo","Cuántos registros fallidos se admiten"],"correct":[2],"explanation":"Controla el paralelismo.","i18n":{"en":{"stem":"What does a Batch Job's maxConcurrency indicate?","options":["Block size","How many steps the job may have and their order","How many blocks process in parallel","How many failures are allowed"],"explanation":"It controls parallelism."}}},{"domain":"D7","source":"bank","stem":"¿Qué tipo de entrada puede recibir un Batch Job?","options":["Solo un único objeto JSON","Solo un archivo XML","Solo un string con los registros separados por saltos de línea","Una colección iterable o un stream de registros"],"correct":[3],"explanation":"La fase de carga divide la entrada en registros.","i18n":{"en":{"stem":"What input can a Batch Job receive?","options":["Only a single JSON object","Only an XML file","Only a string with records separated by newlines","An iterable collection or stream of records"],"explanation":"The load phase splits input into records."}}},{"domain":"D7","source":"bank","stem":"¿Qué pasa con las variables del flujo dentro del Batch Job?","options":["Están disponibles como copia al iniciar el lote","Se comparten y modifican en tiempo real con el flujo","Se borran al iniciar el lote","Se convierten en registros"],"correct":[0],"explanation":"Los cambios dentro del lote no vuelven al flujo.","i18n":{"en":{"stem":"What happens to flow variables inside the Batch Job?","options":["They're available as a copy when the job starts","They're shared and changed live with the flow","They're cleared when the job starts","They become records"],"explanation":"Changes inside don't return to the flow."}}},{"domain":"D7","source":"bank","stem":"¿Qué devuelve al flujo invocante el componente Batch Job?","options":["Nada, el flujo se detiene","Los registros fallidos","Una instancia de lote (BatchJobInstance)","El resultado final del lote"],"correct":[2],"explanation":"El flujo continúa con información de la instancia.","i18n":{"en":{"stem":"What does the Batch Job component return to the invoking flow?","options":["Nothing, the flow stops","Failed records","A batch instance (BatchJobInstance)","The final job result"],"explanation":"The flow continues with instance info."}}},{"domain":"D7","source":"bank","stem":"¿Qué conviene usar dentro de un For Each para que un error en un elemento no detenga los demás?","options":["Un Choice sin rutas","Un Logger antes del For Each","Un Scheduler","Un ámbito Try con On Error Continue"],"correct":[3],"explanation":"Captura el error por elemento.","i18n":{"en":{"stem":"What keeps an element's error from stopping the rest inside a For Each?","options":["A Choice with no routes","A Logger before the For Each","A Scheduler","A Try scope with On Error Continue"],"explanation":"Catches the error per element."}}},{"domain":"D7","source":"bank","stem":"¿Qué dos datos ofrece el BatchJobResult en On Complete? (Elige 2)","options":["La configuración del HTTP Listener","Registros fallidos","Registros totales procesados","El contenido de cada registro","El número de workers"],"correct":[1,2],"explanation":"Estadísticas del lote.","i18n":{"en":{"stem":"Which two items does BatchJobResult offer in On Complete? (Choose 2)","options":["HTTP Listener config","Failed records","Total processed records","Each record's content","Worker count"],"explanation":"Job statistics."}}},{"domain":"D7","source":"bank","stem":"¿Qué recomienda MuleSoft para colecciones pequeñas en memoria que deben procesarse rápido?","options":["Una cola externa de Anypoint MQ por cada elemento de la colección","Batch Job siempre","For Each o Parallel For Each","Un Scheduler por elemento"],"correct":[2],"explanation":"Batch tiene sobrecarga de persistencia.","i18n":{"en":{"stem":"What does MuleSoft recommend for small in-memory collections needing quick processing?","options":["An external Anypoint MQ queue per collection element","Always Batch Job","For Each or Parallel For Each","A Scheduler per element"],"explanation":"Batch has persistence overhead."}}},{"domain":"D7","source":"bank","stem":"¿Qué ocurre si la app se reinicia a mitad de un Batch Job?","options":["El lote puede reanudarse con los registros pendientes","Se borra la aplicación y hay que volver a desplegarla desde cero","Se pierden todos los registros","Se reprocesa todo desde cero siempre"],"correct":[0],"explanation":"La persistencia permite reanudar.","i18n":{"en":{"stem":"What happens if the app restarts mid-Batch Job?","options":["The job can resume with pending records","The app is deleted and must be redeployed from scratch","All records are lost","Everything always reprocesses from scratch"],"explanation":"Persistence enables resuming."}}},{"domain":"D7","source":"bank","stem":"¿Qué conviene en un lote para tratar los registros que fallaron?","options":["Un Logger en On Complete solamente","Ignorarlos","Un step con accept policy ONLY_FAILURES","Un step sin política"],"correct":[2],"explanation":"Permite reportar o reintentar fallidos.","i18n":{"en":{"stem":"What's advisable in a batch to handle failed records?","options":["Only a Logger in On Complete","Ignore them","A step with ONLY_FAILURES accept policy","A step with no policy"],"explanation":"It allows reporting or retrying failures."}}},{"domain":"D7","source":"bank","stem":"¿Qué indica el modo streaming del Batch Aggregator?","options":["Agrega en memoria sin límite","Procesa un único registro","Procesa todos los registros del step como un stream sin tamaño fijo","Desactiva la agregación y procesa cada registro por separado"],"correct":[2],"explanation":"Útil para escribir archivos grandes.","i18n":{"en":{"stem":"What does Batch Aggregator streaming mode do?","options":["Aggregates in memory without limit","Processes a single record","Processes all the step's records as a stream with no fixed size","Disables aggregation and processes each record separately"],"explanation":"Useful for writing large files."}}},{"domain":"D7","source":"bank","stem":"¿Qué estructura de datos devuelve Parallel For Each si una ruta falla?","options":["Un payload vacío","El payload original","Un error compuesto con los resultados y fallos","Solo los resultados exitosos sin error"],"correct":[2],"explanation":"MULE:COMPOSITE_ROUTING.","i18n":{"en":{"stem":"What does Parallel For Each return if a route fails?","options":["An empty payload","The original payload","A composite error with results and failures","Only successful results with no error"],"explanation":"MULE:COMPOSITE_ROUTING."}}},{"domain":"D7","source":"bank","stem":"¿Qué se puede configurar en Parallel For Each para limitar hilos?","options":["batchSize","maxConcurrency","blockSize","counterVariableName"],"correct":[1],"explanation":"Controla el paralelismo.","i18n":{"en":{"stem":"What can be set on Parallel For Each to limit threads?","options":["batchSize","maxConcurrency","blockSize","counterVariableName"],"explanation":"It controls parallelism."}}},{"domain":"D7","source":"bank","stem":"¿Qué dos orígenes encajan con procesamiento de registros programado? (Elige 2)","options":["On Table Row","HTTP Listener","Scheduler","Logger","Flow Reference"],"correct":[0,2],"explanation":"Disparadores por tiempo o por datos.","i18n":{"en":{"stem":"Which two sources fit scheduled record processing? (Choose 2)","options":["On Table Row","HTTP Listener","Scheduler","Logger","Flow Reference"],"explanation":"Time- or data-triggered."}}},{"domain":"D7","source":"bank","stem":"¿Qué conviene si un Batch Job procesa datos sensibles?","options":["Revisar dónde persisten los registros y su seguridad","Registrar cada registro completo en el log","Usar maxFailedRecords 0 siempre","Desactivar el manejo de errores"],"correct":[0],"explanation":"Los registros se persisten temporalmente.","i18n":{"en":{"stem":"What's advisable if a Batch Job handles sensitive data?","options":["Review where records persist and their security","Log every full record","Always use maxFailedRecords 0","Disable error handling"],"explanation":"Records persist temporarily."}}},{"domain":"D8","source":"bank","stem":"¿Qué separa la cabecera del cuerpo en un script DataWeave?","options":["Dos puntos","Tres guiones (---)","Una línea en blanco","Un punto y coma"],"correct":[1],"explanation":"Header y body separados por ---.","i18n":{"en":{"stem":"What separates header from body in a DataWeave script?","options":["A colon","Three dashes (---)","A blank line","A semicolon"],"explanation":"Header and body separated by ---."}}},{"domain":"D8","source":"bank","stem":"¿Qué directiva define el formato de salida en DataWeave?","options":["type json declarado en la cabecera del script","import json","%dw 2.0 únicamente","output application/json"],"correct":[3],"explanation":"output indica el MIME de salida.","i18n":{"en":{"stem":"Which directive defines the output format in DataWeave?","options":["type json declared in the script header","import json","Only %dw 2.0","output application/json"],"explanation":"output gives the output MIME."}}},{"domain":"D8","source":"bank","stem":"¿Qué función transforma cada elemento de un array?","options":["map","pluck","reduce","filter"],"correct":[0],"explanation":"map aplica una función a cada elemento.","i18n":{"en":{"stem":"Which function transforms each element of an array?","options":["map","pluck","reduce","filter"],"explanation":"map applies a function to each element."}}},{"domain":"D8","source":"bank","stem":"¿Qué representan $ y $$ dentro de map?","options":["El payload y los atributos","El primer y último elemento","La clave y el valor de un objeto","El elemento y su índice"],"correct":[3],"explanation":"$ = item, $$ = index.","i18n":{"en":{"stem":"What do $ and $$ represent inside map?","options":["Payload and attributes","First and last element","An object's key and value","The element and its index"],"explanation":"$ = item, $$ = index."}}},{"domain":"D8","source":"bank","stem":"¿Qué función devuelve solo los elementos que cumplen una condición?","options":["joinBy","map","filter","flatten"],"correct":[2],"explanation":"payload filter ($.status == \"open\").","i18n":{"en":{"stem":"Which function returns only elements meeting a condition?","options":["joinBy","map","filter","flatten"],"explanation":"payload filter ($.status == \"open\")."}}},{"domain":"D8","source":"bank","stem":"¿Qué función acumula un array en un único valor, como una suma?","options":["map","reduce","distinctBy","groupBy"],"correct":[1],"explanation":"reduce((item, acc = 0) -> acc + item).","i18n":{"en":{"stem":"Which function accumulates an array into one value, like a sum?","options":["map","reduce","distinctBy","groupBy"],"explanation":"reduce((item, acc = 0) -> acc + item)."}}},{"domain":"D8","source":"bank","stem":"¿Qué función agrupa elementos por un criterio y devuelve un objeto?","options":["groupBy","splitBy","pluck","orderBy"],"correct":[0],"explanation":"payload groupBy $.country.","i18n":{"en":{"stem":"Which function groups elements by a criterion returning an object?","options":["groupBy","splitBy","pluck","orderBy"],"explanation":"payload groupBy $.country."}}},{"domain":"D8","source":"bank","stem":"¿Qué función transforma un objeto en un array a partir de sus pares clave-valor?","options":["reduce","mapObject","pluck","flatten"],"correct":[2],"explanation":"pluck itera claves y valores devolviendo array.","i18n":{"en":{"stem":"Which function turns an object into an array from its key-value pairs?","options":["reduce","mapObject","pluck","flatten"],"explanation":"pluck iterates keys and values returning an array."}}},{"domain":"D8","source":"bank","stem":"¿Qué función transforma las claves y valores de un objeto devolviendo otro objeto?","options":["mapObject","map, aplicado directamente sobre el objeto de entrada","filter","pluck"],"correct":[0],"explanation":"mapObject ((v, k) -> ...).","i18n":{"en":{"stem":"Which function transforms an object's keys and values returning an object?","options":["mapObject","map, applied directly to the input object","filter","pluck"],"explanation":"mapObject ((v, k) -> ...)."}}},{"domain":"D8","source":"bank","stem":"¿Qué función ordena un array por un campo?","options":["distinctBy","orderBy","sizeOf","groupBy"],"correct":[1],"explanation":"orderBy $.date; para descendente se invierte con [-1 to 0].","i18n":{"en":{"stem":"Which function sorts an array by a field?","options":["distinctBy","orderBy","sizeOf","groupBy"],"explanation":"orderBy $.date; reverse with [-1 to 0] for desc."}}},{"domain":"D8","source":"bank","stem":"¿Qué función elimina duplicados según un criterio?","options":["joinBy","flatten","distinctBy","filter"],"c