ipo raíz.","i18n":{"en":{"stem":"Which generic error type catches any error?","options":["HTTP:ANY","MULE:ALL","ERROR:*","ANY"],"explanation":"ANY is the root type."}}},{"domain":"D10","source":"bank","stem":"¿Qué ámbito reintenta un grupo de procesadores hasta que funcione o se agoten los intentos?","options":["Async","For Each","Until Successful","Try"],"correct":[2],"explanation":"maxRetries y millisBetweenRetries.","i18n":{"en":{"stem":"Which scope retries processors until success or attempts run out?","options":["Async","For Each","Until Successful","Try"],"explanation":"maxRetries and millisBetweenRetries."}}},{"domain":"D10","source":"bank","stem":"¿Qué error se lanza cuando Until Successful agota los reintentos?","options":["HTTP:TIMEOUT","MULE:RETRY_EXHAUSTED","MULE:EXPRESSION","ANY, porque Until Successful no tiene un tipo propio"],"correct":[1],"explanation":"Indica fin de reintentos.","i18n":{"en":{"stem":"Which error is raised when Until Successful exhausts retries?","options":["HTTP:TIMEOUT","MULE:RETRY_EXHAUSTED","MULE:EXPRESSION","ANY, since Until Successful has no type of its own"],"explanation":"It signals retries are exhausted."}}},{"domain":"D10","source":"bank","stem":"Un flujo A llama a B con Flow Reference. B tiene On Error Continue y falla. ¿Qué ve A?","options":["Un 500 automático","Una ejecución correcta con el payload del manejador de B","El error de B propagado","Nada: la ejecución de A queda en pausa sin respuesta"],"correct":[1],"explanation":"On Error Continue no propaga.","i18n":{"en":{"stem":"Flow A calls B via Flow Reference. B has On Error Continue and fails. What does A see?","options":["An automatic 500","A successful run with B's handler payload","B's error propagated","Nothing: A's execution hangs with no response"],"explanation":"On Error Continue doesn't propagate."}}},{"domain":"D10","source":"bank","stem":"Un flujo A llama a B con Flow Reference. B tiene On Error Propagate. ¿Qué ocurre en A?","options":["A continúa como si nada","A se reinicia y vuelve a llamar a B automáticamente","A recibe un payload vacío","El error llega a A y se gestiona con su manejo de errores"],"correct":[3],"explanation":"El error se propaga al llamador.","i18n":{"en":{"stem":"Flow A calls B via Flow Reference. B has On Error Propagate. What happens in A?","options":["A continues as if nothing happened","A restarts and calls B again automatically","A gets an empty payload","The error reaches A and is handled by A's error handling"],"explanation":"The error propagates to the caller."}}},{"domain":"D10","source":"bank","stem":"¿Qué dos datos se suelen devolver al cliente en una respuesta de error bien diseñada? (Elige 2)","options":["El SQL ejecutado","Un mensaje descriptivo","Credenciales internas","La traza de pila completa","Un código o identificador de error"],"correct":[1,4],"explanation":"Información útil sin exponer internos.","i18n":{"en":{"stem":"Which two items does a well-designed error response return? (Choose 2)","options":["The executed SQL","A descriptive message","Internal credentials","The full stack trace","An error code or identifier"],"explanation":"Useful info without exposing internals."}}},{"domain":"D10","source":"bank","stem":"¿Dónde se configura el código de estado HTTP para respuestas de error del listener?","options":["En Exchange, dentro de la documentación de la API","En el Logger","En el pom.xml","En la sección Error Response del HTTP Listener"],"correct":[3],"explanation":"Se suele usar una variable httpStatus.","i18n":{"en":{"stem":"Where is the HTTP status for listener error responses configured?","options":["In Exchange, within the API documentation","In the Logger","In pom.xml","In the HTTP Listener's Error Response section"],"explanation":"Often an httpStatus variable is used."}}},{"domain":"D10","source":"bank","stem":"¿Qué patrón es común para fijar el código de error de la respuesta HTTP?","options":["Guardar el código en una variable y usarla en la respuesta del listener